window.STORY_CATEGORIES = window.STORY_CATEGORIES || {}; window.STORY_CATEGORIES[1] = [{"id":1,"category_id":1,"category_code":"s1","source_id":1,"title":"بهلول در نزد خلیفه","content":"روزی بهلول پیش خلیفه((هارون الرشید)) نشسته بود،جمع زیادی از بزرگان خدمت خلیفه بودند،طبق معمول، خلیفه هوس کرد سر به سر بهلول بگذارد. دراین هنگام صدای شیعۀ اسبی از اصطبل بلند شد. خلیفه به مسخره به بهلول گفت: برو ببین این حیوان چه می گوید ، گویا با تو کار دارد.بهلول رفت و برگشت و گفت:این حیوان می گوید: مرد حسابی حیف از تو نیست با این خرها نشسته ای . زودتر از این مجلس بیرون برو. ممکن است که خریت آن ها در تو اثر کند."},{"id":2,"category_id":1,"category_code":"s1","source_id":2,"title":"بهلول و خوراک پز مکار","content":"یک روز عربی ازبازار عبور میکرد که چشمش به دکان خوراک پزی افتاد از بخاری که از سر دیگ بلند میشد خوشش آمد تکه نانی که داشت بر سر آن میگرفت و میخورد.هنگام رفتن صاحب دکان گفت تو از بخار دیگ من استفاده کردی وباید پولش را بدهی٬مردم جمع شدند. مرد بیچاره که از همه جا درمانده بود بهلول را دید که از آنجا میگذشت از بهلول تقاضای قضاوت کرد ،بهلول به آشپز گفت آیا این مرد از غذای تو خورده است؟ \r\nآشپز گفت نه ولی از بوی آن استفاده کرده است. بهلول چند سکه نقره از جیبش در آورد و به آشپز نشان داد وبه زمین ریخت وگفت؟ ای آشپز صدای پول را تحویل بگیر. \r\nآشپز با کمال تحیر گفت :این چه قسم پول دادن است؟ بهلول گفت مطابق عدالت است: کسی که بوی غذا را بفروشد در عوض باید صدای پول دریافت کند.\r\n"},{"id":3,"category_id":1,"category_code":"s1","source_id":3,"title":"بهلول و قبرستان","content":"زاهدی گفت: روزی به گورستان رفتم و بهلول را در آنجا دیدم پرسیدمش اینجا چه می کنی؟ \r\nگفت: با مردمانی همنشینی همی کنم که آزارم نمی دهند، اگر از عقبی غافل شوم یادآوریم می کنند و اگر غایب شوم غیبتم نمی کنند.\r\n"},{"id":4,"category_id":1,"category_code":"s1","source_id":4,"title":"یکی بود ، یکی نبود","content":"یکی بود ، یکی نبود. آن یکی که وجود داشت ، چه کسی بود؟ همان خدا بود وغیر از خدا هیچکس نبود. این قصه را جدی بگیرید که غیر از خدا هیچ کس نیست. \r\nشخصی می گفت: می خواهم مردی خردمند و فرزانه را بیابم تا در مشکلات زندگیم با او مشورت کنم . یکی به او گفت: در شهر ما، فقط یک نفر عاقل و خردمند است که آن هم خود را به دیوانگی زده است . اگر سراغ او را بگیری می توانی اکنون او را درمیان کودکان بینی که روی یک چوب سوار شده و با آنان بازی می کند. \r\nآن جوینده می رود و او را در میان کودکان پیدا می کند و صدایش می زند و می گوید: ای سوار بر چوب، یک لحظه نیز اسب خود را به سوی من بران . عاقل دیوانه نما به سوی او می تازد و می گوید: زود باش حرف بزن، چه می خواهی؟ من نمی توانم زیاد توقف کنم، چون اسبم چموش است و به تو لگد می زند! \r\nآن مرد می گوید: می خواهم از این محله زنی اختیار کنم به نظر تو کدام زنی را بگیرم که مناسب حال من باشد ؟ عاقل دیوانه نما می گوید: به طور کلی در دنیا، زن بر سه نوع است: دو نوع آن باعث رنج و ناراحتی است و نوع سوم مانند گنج سرشار از ثروت و مکنت . از این سه قسم زن ، یک قسم آن ، کاملا در اختیار تو است و همه مواهب و خوبی های آن برای تو . و قسم دیگر ، تنها نیمِ آن به تو تعلق دارد و نیم دیگر آن در اختیار تو نیست . ولی قسم سوم به قدری از تو جداست که گویی اصلا به تو تعلق ندارد . حالا که جواب سئوالت را شنیدی زود برو دنبال کارت که ممکن است اسبم به تو لگد بزند و نقش بر زمینت کند. \r\nعاقل دیوانه نما این سخنان را گفت و شتابان به میان کودکان رفت و مشغول بازی شد . ولی از این طرف نیز مرد بیچاره مبهوت و متحیر بر جای خود ایستاده بود و از آن حرفها چیزی سر در نیاورده بود . از اینرو ملتمسانه او را صدا کرد و گفت: بیا مقصودت را از این حرفها بیان کن . عاقل دیوانه نما دوباره به سوی او دوید و گفت: آن زن که به طور کامل به تو تعلق دارد ، دوشیزه و باکره است که موجب نشاط تو می شود . و آن زن که فقط نیمی از او به تو تعلق دارد ، بیوه زن فاقد فرزند است . ولی آن زنی که اصلا به تو تعلق ندارد ، بیوه زنی است که از شوی پیشین خود فرزندی نیز دارد، زیرا وجود این فرزند ، همیشه این زن را به یاد شوهر قبلی خود می اندازد . حالا که این حرفها را شنیدی ، برو کنار که اسبم به تو لگد نزند . این را گفت و دوباره به میان کودکان رفت. \r\nآن مرد دوباره فریاد زد: ای خردمند فرزانه ، یک سوال دیگر دارم . خواهش می کنم آن را نیز پاسخ ده تا دیگر بروم . عاقل دیوانه نما می گوید: زود سوالت را بیان کن . مرد می پرسد: تو با این همه عقل و فهم ، چرا رفتارهای کودکانه و دیوانه وار انجام می دهی؟ پاسخ می دهد: این اوباش ( دستگاه حکومتی وقت ) به این فکر افتاده اند که مرا قاضی شهر کنند، من خیلی کوشیدم که زیر بار این کار نروم ، ولی دست از سرم برنداشتند ، چاره ای ندیدم جز آنکه خود را به دیوانگی بزنم تا در این دستگاه ظالم قاضی نشوم.\r\n"},{"id":5,"category_id":1,"category_code":"s1","source_id":5,"title":"حمام رفتن بهلول","content":"روزی بهلول به حمام رفت ولی خدمه حمام به او بی اعتنایی نمودند و آن قسم که دلخواه بهلول بود او را کیسه ننمودند. با این حال وقت خروج از حمام بهلول ده دینار که همراه داشت را به استاد حمام داد و کارگران چون این بذل و بخشش را دیدند همگی پشیمان شدند که چرا نسبت به او بی اعتنایی کردند.\r\nبهلول باز هفته دیگر به حمام رفت ولی \r\nاین دفعه تمام کارگران با کمال احترام او را شست و شو نموده و مواظبت بسیار نمودند ، ولی با این همه سعی و کوشش کارگران موقع خروج از حمام بهلول فقط یک دینار به آنها داد ، حمامی ها متغیر گردیده پرسیدند سبب بخشش بی جهت هفته قبل و رفتار امروزت چیست ؟\r\nبهلول گفت: مزد امروز حمام را هفته قبل که حمام آمده پرداخت نمودم و مزد آن روز حمام را امروز می پردازم تا شماها ادب و رعایت مشتری های خود را بنمایید.\r\n"},{"id":6,"category_id":1,"category_code":"s1","source_id":6,"title":"داستان کلوخ","content":"روزی بهلول داشت از کوچه ای می گذشت شنید که استادی به شاگردهایش می گوید : من در سه مورد با امام صادق(ع) مخالفم.\r\nاول اینکه می گوید خدا دیده نمی شود . پس اگر دیده نمی شود وجود هم ندارد.\r\nدوم می گوید : خدا شیطان را در آتش جهنم می سوزاند در حالی که شیطان خود از جنس آتش است و آتش تاثیری در او ندارد.\r\nسوم هم می گوید : انسان کارهایش را از روی اختیار انجام می دهد در حالی که چنین نیست و از روی اجبار انجام می دهد.\r\nبهلول که شنید فورا کلوخی دست گرفت و به طرف او پرتاب کرد.\r\nاتفاقا کلوخ به وسط پیشانی استاد خورد. استاد و شاگردان در پی او افتادند و او را به نزد خلیفه آوردند.\r\nخلیفه گفت : ماجرا چیست؟ استاد گفت : داشتم به  دانش آموزان درس می دادم که بهلول با کلوخ به سرم زد. و الان درد می کند.\r\nبهلول پرسید : آیا تو درد را می بینی؟\r\nگفت : نه\r\nبهلول گفت : پس دردی وجود ندارد. ثانیا مگر تو از جنس خاک نیستی و این کلوخ هم از جنس خاک پس در تو تاثیری ندارد.\r\nثالثا : مگر نمی گویی انسانها از خود اختیار ندارند ؟ پس من مجبور بودم و سزاوار مجازات نیستم.\r\nاستاد اینها را شنید و خجل شد و از جای برخاست و رفت.\r\n"},{"id":7,"category_id":1,"category_code":"s1","source_id":7,"title":"سوال هارون درباره امین و مامون","content":"آورده اند که روزی بهلول به قصر هارون رفت و در بین راه هارون را دید . هارون پرسید بهلول کجا میروی ؟ بهلول جواب داد: به نزد تو می آیم . هارون گفت :من به قصد رفتن به مکتب خانه می روم تا از نزدیک وضع فرزندانم امین و مامون را ببینم و چنانچه مایل باشی می توانی همراه من بیایی .بهلول قبول نمود و به اتفاق هارون وارد مکتب خانه شدند ولی آن وقت امین و مامون برای چند دقیقه اجازه گرفته و بیرون رفته بودند . هارون از معلم از وضع امین و مامون سولاتی نمود . معلم گفت: \r\nامین که فرزند زبیده که سرور زنان عرب است ولی بسیار کو دن و بی هوش است و بلعکس مامون بسیاربافراست و زیرک و چیز فهم . هارون قبول ننمود \r\nآموزگار کاغذی زیر فرش محل نشستن مامون گذارد و خشتی هم زیر فرش امین نهاد و پس از چنددقیقه که امین و مامون وارد مکتبخانه شدند٬ و چون پدر خود را دیدند زمین ادب را بوسه داده و سر جای خود نشستند . مامون چون نشست متفکر به سقف و اطراف خود نگاه می کرد . معلم به مامون گفت :تو را چه می شود که چنین متفکری ؟\r\nمامون جواب داد ، از موقعی که از مکتب خانه خارج شدم و تا به حال که نشسته ام یا زمین به اندازه کاغذی بالا آمده یا اینکه سقف به همین اندازه پایین رفته است .در این حال آموزگار از امین سوال نمود آیا تو هم چنین احساسی می نمایی ؟امین جواب داد : چیزی حس نمی کنم . آموزگار لبخندی زده و آن دو را مرخص نمود . چون امین ومامون از مکتبخانه خارج شدند معلم به هارون گفت : بحمدالله که به حضرت خلیفه حرف من ثابت شد.\r\nخلیفه سوال نمود : آیا سبب آن را می دانی ؟بهلول جواب داد اگر به من امان دهی حاضرم علت آن را بگویم . هارون جواب داد در امانی هرچه میدانی بگو . بهلول گفت: \r\nذکاوت و چالاکی اولاد از دو جهت است . جهت اول چنانچه مرد و زن به میل و رغبت سرشار وشهوت طبیعی با هم آمیزش نمایند اولاد آنها با ذکاوت و زیرک می شود و سبب دوم چنانچه زن وشوهر از حیث خون و نژاد با هم تفاوت داشته باشند ، اولاد آنها زیرک و باهوش و قوی می شود چنانچه این امر در درختان و حیوانات هم به تجربه رسیده است و چنانچه درخت میوه را به درخت میوه دیگرپیوند بزنند آن میوه آن شاخه پیوند خورده بسیار مرغوب و اعلا می شود و نیز اگر دو حیوان مثلاً الاغ واسب با هم آمیزش دهند قاطر از آن دو متولد می شود که بسیار باهوش و قوی و چالاک می باشد. \r\nبنابراین امین که فراست خوبی ندارد از این سبب است که خلیفه و زبیده از یک خون و یک نژاد میباشند و مامون که با این فراست و ذکاوت قوی می باشد از آن لحاظ است که مادر او از نژادی غریب وبا خون خلیفه تفاوت بسیار دارد. \r\nخلیفه از جواب بهلول خنده نمود و گفت : از دیوانه غیر از این توقعی نمی توان داشت . ولی معلم در دل حرف بهلول را تصدیق نمود.\r\n"},{"id":8,"category_id":1,"category_code":"s1","source_id":8,"title":"فروش بهشت","content":"بهلول هر وقت دلش می گرفت به کنار رودخانه می آمد. در ساحل می نشست و به آب نگاه می کرد.\r\n\r\nپاکی و طراوت آب، غصه هایش را می شست. اگر بیکار بود همانجا می نشست و مثل بچه ها گِل بازی می کرد.آن روز هم داشت با گِل های کنار رودخانه، خانه می ساخت. جلوی خانه باغچه ایی درست کرد و توی باغچه چند ساقه علف و گُل صحرایی گذاشت.\r\n ناگهان صدای پایی شنید برگشت و نگاه کرد. زبیده خاتون (همسر خلیفه) با یکی از خدمتکارانش به طرف او آمد. به کارش ادامه داد. همسر خلیفه بالای سرش ایستاد و گفت : بهلول، چه می سازی؟\r\n. بهلول با لحنی جدی گفت: بهشت می سازم\r\n! همسر هارون که می دانست بهلول شوخی می کند، گفت: آن را می فروشی؟\r\n. بهلول گفت : می فروشم\r\n قیمت آن چند دینار است؟\r\nصد دینار.\r\n. زبیده خاتون گفت : من آن را می خرم\r\n بهلول صد دینار را گرفت و گفت : این بهشت مال تو، قباله آن را بعد می نویسم و به تو می دهم.\r\n. زبیده خاتون لبخندی زد و رفت\r\n بهلول سکه ها را گرفت و به طرف شهر رفت. بین راه به هر فقیری رسید یک سکه به او داد. وقتی تمام دینارها را صدقه داد، با خیال راحت به خانه برگشت.\r\n زبیده خاتون همان شب، در خواب، وارد باغ بزرگ و زیبایی شد. در میان باغ، قصرهایی دید که با جواهرات هفت رنگ تزئین شده بود. گلهای باغ، عطر عجیبی داشتند. زیر هر درخت چند کنیز زیبا، آماده به خدمت ایستاده بودند. یکی از کنیزها، ورقی طلایی رنگ به زبیده خاتون داد و گفت : این قباله همان بهشتی است که از بهلول خریده ای!!! \r\n وقتی زبیده از خواب بیدار شد از خوشحالی ماجرای بهشت خریدن و خوابی را که دیده بود برای هارون تعریف کرد.\r\n. صبح زود، هارون یکی از خدمتکارانش را به دنبال بهلول فرستاد\r\nوقتی بهلول به قصر آمد، هارون به او خوش آمد گفت و با مهربانی و گرمی از او استقبال کرد. بعد صد دینار به بهلول داد و گفت : یکی از همان بهشت هایی را که به زبیده فروختی به من هم بفروش!\r\n! بهلول، سکه ها را به هارون پس داد و گفت : به تو نمی فروشم \r\n هارون گفت : اگر مبلغ بیشتری می خواهی، حاضرم بدهم\r\n!!! بهلول گفت : اگر هزار دینار هم بدهی، نمی فروشم\r\n هارون ناراحت شد و پرسید : چرا؟\r\n بهلول گفت : زبیده خاتون، آن بهشت را ندیده خرید، اما تو می دانی و می خواهی بخری، من به تو نمی فروشم.\r\n"},{"id":9,"category_id":1,"category_code":"s1","source_id":9,"title":"حکایت بهلول از ملک و سلطنت","content":"روزی بهلول بر هارون‌الرشید وارد شد.\r\nخلیفه گفت: مرا پندی بده!\r\nبهلول پرسید: اگر در بیابانی بی‌آب، تشنگی بر تو غلبه نماید چندان که مشرف به موت گردی، در مقابل جرعه‌ای آب که عطش تو را فرو نشاند چه می‌دهی؟\r\nگفت : صد دینار طلا\r\nپرسید: اگر صاحب آب به پول رضایت ندهد؟\r\nگفت: نصف پادشاهی‌ام را.\r\nبهلول گفت: حال اگر به حبس‌البول مبتلا گردی و رفع آن نتوانی، چه می‌دهی که آن را علاج کنند؟\r\nگفت: نیم دیگر سلطنتم را.\r\nبهلول گفت: پس ای خلیفه، این سلطنت که به آبی و بولی وابسته است، تو را مغرور نسازد که با خلق خدای به بدی رفتار کنی.\r\n"},{"id":10,"category_id":1,"category_code":"s1","source_id":10,"title":"گول زدن داروغه","content":"آوره اند که داروغه بغداد در بین جمعی ادعا می کرد که تا به حال هیچکس نتوانسته است مرا گول بزند.\r\nبهلول در میان آن جمع بود گفت : گول زدن تو کار آسانی است ولی به زحمتش نمی ارزد \r\nداروغه گفت چون از عهده آن بر نمی آیی این حرف را می زنی . بهلول گفت حیف که الساعه کار\r\nخیلی واجبی دارم والا همین الساعه تو را گول می زدم! \r\nداروغه گفت حاضری بروی و فوری کارت را انجام بدهی و برگردی ؟\r\nبهلول گفت بلی . پس همین جا منتظر من باش فوری می آیم . بهلول رفت و دیگر برنگشت.  داروغه\r\nپس از دو ساعت معطلی بنا کرد به غرغر کردن و بعد گفت این اولین دفعه است که این دیوانه مرا به این\r\nقسم گول زد و چندین ساعت بی جهت مرا معطل و از کار باز نمود.\r\n"},{"id":11,"category_id":1,"category_code":"s1","source_id":11,"title":"بهلول قضاوت کن!","content":"\r\nهارون الرشيد درخواست نمود کسی را برای قضاوت در بغداد انتخاب نمایید.\r\nاطرافیان او همه با هم گفتند عادل تر از بهلول سراغ نداریم او را انتخاب نمایید.\r\nخلیفه دستور داد بهلول را نزد او بیاورند٬\r\nبعد از دیدار با بهلول به او پیشنهاد قاضی شدن در بغداد را داد.\r\n. گفت : من شایسته این مقام نیستم و صلاحیت انجام چنین کاری را ندارم\r\nهارون الرشید گفت : تمام بزرگان بغداد تو را انتخاب کرده اند چگونه است که تو قبول نمی کنی! \r\nبهلول جواب داد : من از اوضاع و احوال خودم بیشتر اطلاع دارم و این سخن یا راست است یا دروغ.\r\nاگر راست است که من به دلیلی که گفتم شایسته این مقام نیستم و اگر هم دروغ باشد که شخص دروغگو صلاحیت قضاوت کردن ندارد! \r\nهارون الرشید اصرار فراوان کرد و بهلول در خواست کرد یک روز به او مهلت دهند تا فکر کند.\r\nفردا صبح اول طلوع بهلول بر چوبی نشست و در خیابان ها فریاد می زد اسبم رم کرده بروید کنار تا زیر سمش گرفتار نشده اید.\r\nمردم گفتند : بهلول دیوانه شده است! \r\nخبر دیوانگی بهلول به خلیفه عباسی رسید! \r\nهارون الرشید لبخند تلخی زد و گفت : او دیوانه نشده است او بخاطر حفظ دینش از دست ما فرار کرده تا در حقوق مردم دخالتی نداشته باشد. \r\nحتی زمانی که از غذای خلیفه برای او می آوردند می گفت : این غذا را به سگ ها بدهید بخورند حتی اگر آنها هم بفهمند مال خلیفه است نخواهند خورد.\r\n"},{"id":12,"category_id":1,"category_code":"s1","source_id":12,"title":"بهلول شکم سیر","content":"\r\nروزی از روزها هارون الرشید از بهلول دیوانه پرسید: \r\n بگو ببینم نزد تو ” دوست ترین مردم ” چه کسی است ؟\r\nبهلول پاسخ داد : همان کسی که شکم مرا سیر کند دوست ترین مردم نزد من است! \r\nهارون الرشید گفت : اگر من شکم تو را سیر کنم مرا دوست داری ؟\r\nبهلول با خنده پاسخ داد : دوستی به نسیه و اما و اگر نمی شود!!\r\n"},{"id":13,"category_id":1,"category_code":"s1","source_id":13,"title":"بهلول و دیوانگان","content":"هارون الرشید به همراه مهمانانش عیسی بن جعفر برمکی و مادر جعفر برمکی در قصر نشسته بود و حوصله اش سر رفته بود.\r\nاز سربازان خواست بهلول را بیاورند تا آنها را بخنداند.\r\nسربازان رفتند و بهلول را از میان کودکان شهر گرفته و نزد خلیفه آوردند.\r\nهارون الرشید به بهلول امر کرد چند دیوانه برای ما بشمار\r\nبهلول گفت : اولین دیوانه خودم هستم و با اشاره دست به سمت مادر جعفر برمکی گفت این دومین دیوانه هست.\r\nعیسی با حالتی عصبی فریاد زد : وای بر تو برای مادر جعفر چنین حرفی می زنی ؟\r\n خندید و گفت : صاحب اربده سومین دیوانه هست\r\nهارون از کوره در رفت و فریاد زد: \r\nاین دیوانه را از قصر بیرون کنید آبرویمان را برد\r\nبهلول در حالی که روی زمین کشیده می شد گفت : تو هم چهارمی هستی هارون!\r\n"},{"id":14,"category_id":1,"category_code":"s1","source_id":14,"title":"بهلول و تخت شاهی","content":"روزی بهلول وارد قصر هارون الرشید شد و چون مسند خلافت را خالی و بلامانع دید جلو رفته و بدون ترس و واهمه بر تخت خلیفه نشست.\r\nغلامان دربار چون آن حال بدیدند به ضرب چوب و تازیانه بهلول را از تخت پایین کشیدند٬\r\nهنگامی که خلیفه وارد شد بهلول را در حالتی بهم ریخته دید که گریه می کند!\r\nاز نگهبانان سبب گریه ی او را پرسید٬\r\nنگهبانان گفتند : چون در مکان مخصوص شما نشسته بود او را از آنجا دور کردیم\r\nهارون ایشان را ملامت کرد و بهلول را دلداری داده و نوازش نمود.\r\n گفت : من برای خود گریه نمی کنم بلکه به حال تو می گریم\r\nزیرا که من چند لحظه در مسند تو نشستم اینقدر صدمه دیدم و اذیت و آزار کشیدم\r\nدر این اندیشه ام که تو که یک عمر بر این مسند نشسته ای  چه مقدار آزار خواهی کشید و صدمه خواهی دید.\r\nتو به عاقبت کار خود نمی اندیشی و در فکر کارهای خود نیستی!!\r\n"},{"id":15,"category_id":1,"category_code":"s1","source_id":15,"title":"بهلول و کمک به نیازمندان","content":"\r\nروزی هارون الرشید به سربازانش دستور داد تا بهلول دیوانه را به نزد او بیاورند.\r\nسربازان پس از ساعتی گشت زدن در شهر بهلول دیوانه را در حال بازی با کودکان یافتند و او را به نزد هارون الرشید بردند.\r\nهارون الرشید با روی باز از بهلول استقبال کرد و گفت مبلغی پول  به بهلول بدهند که بین فقرا و نیازمندان تقسیم کند و از آنها بخواهد برای سلامتی و طول عمر هارون الرشید دعا کنند.\r\nبهلول وجه را از خزانه هارون الرشید گرفت و لحظه ای بعد دوباره به نزد خلیفه هارون الرشید رسید.\r\nهارون الرشید با تعجب به بهلول نگاه کرد و گفت ای دیوانه چرا هنوز اینجایی ! چرا برای تقسیم کردن پول به میان فقرا نرفته ای ؟\r\nگفت : هر چه فکر کردم از خلیفه محتاج تر و فقیرتر در این دیار نیافتم!\r\nچرا که می بینم ماموران تو به ضرب تازیانه از مردم باج و خراج می گیرند و در خزانه ی تو می ریزند\r\nاز این جهت دیدم که نیاز تو از همه بیشتر است لذا وجه را آورده ام تا به خودت بازگرداندم!!\r\n"},{"id":16,"category_id":1,"category_code":"s1","source_id":16,"title":"دیدن شیطان","content":"روزی مردی اخمو و بداخلاق از بهلول سوال نمود که خیلی میل دارم که شیطان را ببینم..\r\nبهلول گفت:\r\n«اگر آئینه در خانه نداری در آب زلال نگاه کن شیطان را خواهی دید!!!»\r\n"},{"id":17,"category_id":1,"category_code":"s1","source_id":17,"title":"بهلول در کشتی","content":"آورده اند که یکی از بازرگانان بغداد با غلام خود در کشتی نشسته و به عزم بصره در حرکت بودند و نیز در همان کشتی بهلول و جمعی دیگر بودند . غلام از تلاطم دریا وحشت داشت و مدام گریه و زاری  می نمود. مسافران از گریه و زاری آن غلام به ستوه آمدند و از آن میان بهلول از صاحب غـلام خواسـت تـااجازه دهد به طریقی آن غلام را ساکت نماید. بازرگان اجازه داد . بهلول فوری امر نمود تـا غـلام را بـه دریا انداختند و چون نزدیک به هلاکت رسـید او را بیـرون آوردنـد. غـلام از آن پـس بـه گوشـه ای ازکشتی ساکت و آرام نشست . \r\nاهل کشتی از بهلول سوال نمودند در این عمل چه حکمت بود که غلام ساکت و آرام شد ؟ \r\nبهلول گفت: این غلام قدر عافیت این کشتی را نمی دانست و چون به دریا افتاد فهمید که کـشتی جـای امن و آرامی است .\r\n"},{"id":18,"category_id":1,"category_code":"s1","source_id":18,"title":"بهلول و طبیب","content":"آورده اند که هارون الرشید طبیب مخصوصی جهت دربار خود از یونان خواست . چون آن طبیب وارد بغداد شد هارون الرشید با جلال خاصی آن طبیب را وارد دربار نمود و بسیار با او احترام نمود.تا چند روز ارکان دولت و اکابر شهر بغداد به دیدن آن طبیب می رفتند تا اینکه روز سوم بهلول هم به اتفاق چند تن به دیدن آن طبیب رفت و در ضمن تعارفات و صحبتهای معمولی ناگهان بهلول از آن طبیب سوال نمود : شغل شما چه می باشد ؟\r\nطبیب چون سابقه بهلول را شنیده و او را می شناخت که دیوانه است خواست او را مسخره نمایدبه او جواب داد : من طبیب هستم و مرده ها را زنده می نمایم . بهلول در جواب گفت:\r\nتو زنده ها را نکش، مرده زنده کردنت پیشکش!!\r\nاز جواب بهلول هارون و اهل مجلس خنده بسیار نمودند و طبیب از رو رفت و بغداد را ترک نمود...\r\n"},{"id":19,"category_id":1,"category_code":"s1","source_id":19,"title":"بهلول و صیاد","content":"\r\nآورده اند که خلیفه هارون الرشید با زبیده زن خود نشسته و مشغول بازی شطرنج بودند ، بهلول بر آنها وارد شد او هم نشست و به تماشای آنها مشغول شد. \r\nدر آن حال صیادی زمین ادب را بوسه داد و ماهی بسیار فربه قشنگی را جهت خلیفه آورده بود .هارون در آن روز سر خوش بود امر نمود تا چهار هزار درهم به صیاد انعام بدهند! \r\nزبیده به عمل هارون اعتراض نمود و گفت : این مبلغ برای صیادی زیاد است به جهت اینکه تو باید هر روز به افراد لشگری وکشوری انعام بدهی و چنانکه تو به آنها از این مبلغ کمتر بدهی خواهند گفت که ما به قدر صیادی هم نبودیم و اگر زیاد بدهی خزینه تو به اندک مدتی تهی خواهد شد. \r\nهارون سخن زبیده را پسندیده و گفت الحال چه کنم ؟ گفت صیاد را صدا کن و از او سوال نما این ماهی نر است یا ماده ؟ اگر گفت نر است بگو پسند مانیست و اگر گفت ماده است باز هم بگو پسند ما نیست و او مجبور می شود ماهی را پس ببرد و انعام را بگذارد. بهلول به هارون گفت : فریب زن نخور مزاحم صیاد نشو ولی هارون قبول ننمود صیاد را صدا زد و به او گفت : ماهی نر است یا ماده؟ صیاد باز زمین ادب بوسید و عرض نمود این ماهی نه نر است نه ماده بلکه خنثی است \r\nهارون از این جواب صیاد خوشش آمد و امر نمود تا چهار هزار درهم دیگر هم انعام به او بدهند!! \r\nصیادپولها را گرفته ، در بندی ریخت و موقعی که از پله های قصر پایین می رفت یک درهم از پولها به زمین افتاد . صیاد خم شد و پول را برداشت\r\nزبیده به هارون گفت :این مرد چه اندازه پست همت است که از یک درهم هم نمی گذرد . هارون هم از پست فطرتی صیاد بدش آمد و او را صدازد و باز بهلول گفت مزاحم او نشوید . هارون قبول ننمود و صیاد را صدا زد وگفت : چقدر پست فطرتی که حاضر نیستی حتی یک درهم از این پولها قسمت غلامان من شود. \r\nصیاد باز زمین ادب بوسه زد و عرض کرد : من پست فطرت نیستم . بلکه نمک شناسم و از این جهت پول را برداشتم که دیدم یک طرف این پول آیات قرآن و سمت دیگر آن اسم خلیفه است و چنانچه روی زمین بماند شاید پا به آن نهند و از ادب دور است! \r\nخلیفه باز از سخن صیاد خوشش آمد و امر نمود چهار هزار درهم دیگر هم به صیاد انعام دادند و به بهلول گفت : من از تو دیوانه ترم به جهت اینکه هردفعه مرا مانع شدی من حرف تو را قبول ننمودم و حرف آن زن را به کار بستم و این همه متضرر شدم.\r\n"},{"id":20,"category_id":1,"category_code":"s1","source_id":20,"title":"بهلول و شراب","content":"\r\nخلیفه مشغول صرف شراب بود و خواست خود را از خوردن حرام تبرئه نماید. روزی بهلول بر هارون وارد شد.\r\nبدین لحاظ از بهلول سوال نمود:\r\nاگر کسی انگور خورد حرام است! \r\nبهلول جواب داد نه! \r\nخلیفه گفت :بعد از خوردن انگور آب هم بالای آن خورد چه طور است؟\r\n بهلول جواب داد :اشکالی ندارد\r\nباز خلیفه گفت بعد از خوردن انگور و آب مدتی هم در آفتاب نشیند؟ بهلول گفت: بازهم اشکالی ندارد\r\nخلیفه گفت:پس چطور همین انگور و آب را اگر مدتی در آفتاب گذارند حرام است؟\r\n بهلول جواب داد اگر قدری خاک بر سر انسان ریزند آیا به او صدمه می رساند ؟\r\nخلیفه جواب داد :نه \r\n بهلول گفت :بعد از آن هم مقداری آب بر سر انسان ریزند صدمه می رساند؟\r\nخلیفه جواب داد :نه \r\n بهلول گفت :اگر همین آب و خاک را به هم مخلوط نمایند و از آن خشتی بسازند و به سر انسان بزنند صدمه می رسد یا نه؟\r\nخلیفه : البته سر انسان می شکند \r\nبهلول گفت چنانکه از ترکیب آب و خاک سر آدم می شکند و به او صدمه می رسد ، از ترکیب آب وانگور هم متاعی بدست می آید که از خوردن آن صدمه های فراوان به انسان وارد می آید و خورنده آن حد لازم دارد٬  خلیفه از جواب بهلول متحیر و دستور داد تا بساط شراب را بردارند.\r\n"},{"id":21,"category_id":1,"category_code":"s1","source_id":21,"title":"بهلول و دزد کفش","content":"گویند روزی بهلول با کفش نویی وارد مسجد شد تا نماز بخواند. وی شخصی را دید که دایم به کفشهای او می نگریست! بهلول فهمید که به کفشهایش طمع کرده است پس به ناچار با کفش به نماز ایستاد.\r\nشخص که چنین دید گفت با کفش نماز نباشد.\r\nبهلول گفت اگر نماز نباشد کفش باشد.\r\n"},{"id":22,"category_id":1,"category_code":"s1","source_id":22,"title":"طعام خلیفه","content":"آورده اند که هارون الرشید خوان طعامی برای بهلول فرستاد . خادم خلیفه طعام را نزد بهلول آورد و پیش اوگذاشت و گفت این طعام مخصوص خلیفه است و برای تو فرستاده است تا بخوری. \r\nبهلول طعام را پیش سگی که در آن خرابه بود گذاشت . خادم بانگ به او زد که چرا طعام خلیفه را پیش سگ گذاردی ؟\r\nبهلول گفت: دم مزن اگر سگ بشنود این طعام از آن خلیفه است او هم نخواهد خورد!\r\n"},{"id":23,"category_id":1,"category_code":"s1","source_id":23,"title":"فرزند دختر","content":"اسحاق بن محمد بن صباح امیر کوفه بود . زوجه او دختری زایید . امیر از این جهت بسیار محزون وغمگین گردید و از غذا و آب خوردن خودداری نمود . چون بهلول این مطلب را شنید به نزد وی رفت و گفت: ای امیر این ناله و اندوه برای چیست؟\r\nامیر جواب داد من آرزوی اولادی ذکور را داشتم ، متاسفانه زوجه ام دختری آورده است. \r\nبهلول جواب داد : آیا خوش داشتی که به جای این دختر زیبا و تام الاعضاء و صحیح و سالم ، خداوند پسری دیوانه مثل من به تو عطا می کرد ؟\r\nامیر بی اختیار خنده اش گرفت و شکر خدای را به جای آورد و طعام و آب خواست و اجازه داد تامردم برای تبریک و تهنیت به نزد او بیایند.\r\n"},{"id":24,"category_id":1,"category_code":"s1","source_id":24,"title":"عظیمت داروغه","content":"روزی داروغه بهلول را گفت:تاچند روز دیگر مرا به شهری دیگر می فرستند .اینک از همه خداحافظی میکنم.\r\nبهلول گفت:این مصیبتی عظیم است!داروغه پرسید:برای شما؟؟\r\nگفت:نه برای آن شهر دیگر!!\r\n"},{"id":25,"category_id":1,"category_code":"s1","source_id":25,"title":"بزرگترینها","content":"روزی خلیفه بهلول را پرسید:بزرگترین جانور دریا کدام است؟\r\nگفت:نهنگ\r\nپرسید:بزرگترین جانور خشکی کدام است؟؟\r\nگفت:استغفرا....کدام جانور را جرئت آن باشد که خود را از حضرت خلیفه بزرگتر پندارد؟!\r\n"},{"id":26,"category_id":1,"category_code":"s1","source_id":26,"title":"شکار خلیفه","content":"روزی هارون الرّشید و جمعی از درباریان به شکار رفته بودند.بهلول نیز با آنها بود.\r\nآهویی در شکارگاه ظاهر شد.خلیفه،تیری به سوی آهو افکند ولی تیرش به خطا رفت و آهو گریخت.بهلول گفت:احسنت!!\r\nخلیفه برآشفت و فریاد زد:مرا مسخره میکنی؟؟\r\nبهلول گفت:احسنت من برای آهو بود نه برای خلیفه!\r\n"},{"id":27,"category_id":1,"category_code":"s1","source_id":27,"title":"دوست خلیفه","content":"یکی از خاصان خلیفه از مسیری رد می شد.بهلول بی هوا تنه ای به او زد.آن فرد برآشفت و گفت:می دانی من کی هستم؟\r\nبهلول گفت:بله خوب میدانم.چون قبلا هم تو را دیده ام!\r\nپرسید:درکجا؟\r\nبهلول گفت:در دارالمجانین\r\nآن شخص فریاد زد که:دیوانه!من در بارگاه خلیفه هستم و از خاصان درگاه اویم.\r\nبهلول گفت:من هم همین را گفتم!!\r\n"},{"id":28,"category_id":1,"category_code":"s1","source_id":28,"title":"حکومت بهلول","content":"روزی وزیر هارون به شوخی به بهلول گفت:مبارک است! خلیفه حکومت گرگها و خنزیرها(خوکها) را به تو واگذار کرد!\r\nبهلول بی درنگ گفت:خودت حکومت مرا فهمیدی و تصدیق کردی.از این به بعد مواظب باش که از اطاعت من سرپیچی نکنی.\r\nحضار از سخن بهلول به خنده افتادند و وزیر شرمنده شد.\r\n"},{"id":29,"category_id":1,"category_code":"s1","source_id":29,"title":"بهلول و توانگر","content":"روزی خواجه ای توانگر بهلول را طلبید که مرا دل تنگ است وملولم بیا و ما را بخندان\r\nبهلول گفت:آیا شما را هیچ آئینه ای در خانه نباشد؟؟!\r\nخواجه گفت:در خانه ی من آئینه فراوان است.\r\nبهلول گفت:دیگر به من نیاز نباشد،در آنها بنگرید.خندیدنی ها را خواهند گفت...!\r\n"},{"id":30,"category_id":1,"category_code":"s1","source_id":30,"title":"خواب خلیفه","content":"روزی خلیفه بهلول را احضار کرد که:خوابی دیده ام و میخواهم تعبیرش کنی\r\nبهلول گفت:چیست؟\r\nخلیفه گفت:خواب دیدم به جانور وحشتناکی تبدیل شده ام و نعره زنان به اطراف خود هجوم میبرم و آنچه از خرد و کلان در سر راه خود میبینم در هم شکسته و می بلعم.حالا بگو تعبیرش چیست؟\r\nبهلول گفت:من تعبیر واقعیت ندانم فقط خواب تعبیر میکنم!!\r\n"},{"id":31,"category_id":1,"category_code":"s1","source_id":31,"title":"حکایت بهلول و جنید بغدادی","content":"\r\nشیخ جنید بغدادی به عزم سیر از شهر بغداد بیرون رفت و مریدان از عقب او، شیخ احوال بهلول را پرسید. گفتند او مردی دیوانه است. گفت او را طلب کنید که مرا با او کار است. پس تفحص کردند و او را در صحرایی یافتند.\r\nشیخ پیش او رفت و در مقام حیرت مانده سلام کرد. بهلول جواب سلام او را داده ٬پرسید چه کسی هستی؟ عرض کرد منم شیخ جنید بغدادی.\r\nفرمود تویی شیخ بغداد که مردم را ارشاد می‌کنی؟ عرض کرد آری..\r\nبهلول فرمود طعام چگونه می خوری؟ عرض کرد اول بسم‌الله می‌گویم و از پیش خود می‌خورم و لقمه کوچک برمی‌دارم، به طرف راست دهان می‌گذارم و آهسته می‌جوم و به دیگران نظر نمی‌کنم و در موقع خوردن از یاد حق غافل نمی‌شوم و هر لقمه که می‌خورم بسم‌الله می‌گویم و در اول و آخر دست می‌شویم...\r\nبهلول برخاست و دامن بر شیخ فشاند و فرمود تو می‌خواهی که مرشد خلق باشی در صورتی که هنوز طعام خوردن خود را نمی‌دانی و به راه خود رفت.\r\nمریدان شیخ را گفتند: یا شیخ این مرد دیوانه است. خندید و گفت سخن راست از دیوانه باید شنید و از عقب او روانه شد تا به او رسید. بهلول پرسید: که هستی؟ جواب داد شیخ بغدادی که طعام خوردن خود را نمی‌داند.\r\nبهلول فرمود آیا سخن گفتن خود را می‌دانی؟ عرض کرد آری.\r\nبهلول پرسید چگونه سخن می‌گویی؟ عرض کرد سخن به قدر می‌گویم و بی‌حساب نمی‌گویم و به قدر فهم مستمعان می‌گویم و خلق را به خدا و رسول دعوت می‌کنم و چندان سخن نمی‌گویم که مردم از من ملول شوند و دقایق علوم ظاهر و باطن را رعایت می‌کنم. پس هر چه تعلق به آداب کلام داشت بیان کرد.\r\nبهلول گفت گذشته از طعام خوردن سخن گفتن را هم نمی‌دانی..\r\nپس برخاست و دامن بر شیخ افشاند و برفت. مریدان گفتند یا شیخ دیدی این مرد دیوانه است؟ تو از دیوانه چه توقع داری؟ جنید گفت مرا با او کار است، شما نمی‌دانید.\r\nباز به دنبال او رفت تا به او رسید. بهلول گفت از من چه می‌خواهی؟ تو که آداب طعام خوردن و سخن گفتن خود را نمی‌دانی، آیا آداب خوابیدن خود را می‌دانی؟ عرض کرد آری.\r\nبهلول فرمود چگونه می‌خوابی؟ عرض کرد چون از نماز عشا فارغ شدم داخل جامه‌ خواب می‌شوم، پس آنچه آداب خوابیدن که از حضرت رسول (علیه‌السلام) رسیده بود بیان کرد. بهلول گفت فهمیدم که آداب خوابیدن را هم نمی‌دانی.\r\nخواست برخیزد جنید دامنش را بگرفت و گفت ای بهلول من هیچ نمی‌دانم، تو قربه‌الی‌الله مرا بیاموز.\r\nبهلول گفت چون به نادانی خود معترف شدی تو را بیاموزم.\r\nبدانکه اینها که تو گفتی همه فرع است و اصل در خوردن طعام آن است که لقمه حلال باید و اگر حرام را صد از این گونه آداب به جا بیاوری فایده ندارد و سبب تاریکی دل شود. جنید گفت جزاک الله خیراً!\r\nو در سخن گفتن باید دل پاک باشد و نیت درست باشد و آن گفتن برای رضای خدای باشد و اگر برای غرضی یا مطلب دنیا باشد بیهوده و هرزه بود.. هر عبارت که بگویی آن وبال تو باشد. پس سکوت و خاموشی بهتر و نیکوتر باشد.\r\nو در خواب کردن این‌ها که گفتی همه فرع است. اصل این است که در وقت خوابیدن در دل تو بغض و کینه و حسد بشری نباشد.\r\n"},{"id":32,"category_id":1,"category_code":"s1","source_id":32,"title":"بهلول و تقسیم عادلانه","content":"گویند روزگاری کار بر ایرانیان دشوار افتاده بود، و آن دشواری دندان طمع عثمانی را تیز کرده و سلطان عثمانی به طمع جهانگشایی چشم بر دشواری‌های ایرانیان دوخته بود. پس ایلچی فرستاد که همان سفیر است، تا ایرانیان را بترساند و پس از آن کار خویش کند.\r\n\r\nایلچی آمد و آنچنان که رسم ماست با عزت و احترام او را در کاخی نشاندند و خدمت‌ها کردند. به روز مذاکره رسمی وکیلان همه یک رای شدند که این مذاکره حساس است و بدون بهلول رفتن به آن٬ دور از تدبیر کشورداری است. وزیر که خردمند بود گفته وکیلان مردم پذیرفت و بهلول را خواست و خواهش کرد او هم همراه باشد. بهلول که هشیار بود و با نیک و بد جهان آشنا، هیچ نگفت و پذیرفت.\r\nسفره گستردند و آنچنان که رسم ماست به میهمان‌نوازی پرداختند. بهلول روبروی سفیر عثمانی در آن سوی سفره نشسته بود. پلو آوردند در سینی‌های بزرگ، و بر سفره چیدند، زعفران بر آن ریخته و به زیبایی آراسته. سفیر عثمانی به ناگهان کاردی برگرفت و هر چه زعفران بر روی پلو بود به سوی خویش کشید و نگاهی به بهلول انداخت. بهلول هیچ نگفت. قاشقی برداشت و با ادب بسیار نیمی از زعفران سوی خود آورد و نیم دیگر برای سفیر گذاشت. سفیر برآشفت و با کارد خویش پلو را به هم زدن آغاز کرد. آنچنان بلبشویی شد که کمتر زعفرانی دیده می‌شد و بخشی از پلو هم به هر سوی سفره پراکنده شده بود. بهلول دست در جیب کرد و دو گردو به روی پلو انداخت. سفیر آشفته شد و تاب نیاورد و خوراک وانهاد و دستور رفتن داد.\r\n\r\nعثمانی‌ها بی‌ خوردن خوراک و با شتاب بر اسب‌ها نشسته و رفتند. وزیر که خردمند بود اما در کار بهلول وامانده و از ترس رنگش مانند زعفران گشته، نالان شد و به بهلول گفت این چه کاری بود، همه کاسه‌کوزه‌ها به هم ریخته شد و آینده ناروشن است. بهلول پاسخ داد مذاکره پایان یافت و بهتر از آن شدنی نبود. وزیر چگونگی آن پرسید. همگان ادب بهلول بر سفره دیده بودند و او بی‌کم و کاست تدبیر خویش نیز بگفت.\r\n\r\nسفیر آنگاه که کارد برگرفت و همه زعفران سوی خویش کشید، دو چیز گفت. نخست آن که با کارد آغازید و نه با قاشق، یعنی که تیغ می‌کشیم و دیگر اینکه همه جهان از آن ماست، یعنی تسلیم شوید. من قاشق برداشتم و نیمی پیش کشیدم. یعنی که نیازی به تیغ کشیدن نیست، نیم از آن شما و نیمی هم از ما. او برآشفت و پلو به هم زد و من نیز دو گردو انداختم. \r\nگردو که در قم و ری به آن جوز هم گویند، چون دو شود همه دانند که چه گوید، شما چگونه ندانی، مگر ایرانی نیستی. وزیر شرمگین شد و آفرین‌ها بر بهلول خواند.\r\n"},{"id":33,"category_id":1,"category_code":"s1","source_id":33,"title":"جنون","content":"\r\nكسي بهلول را گفت:\r\nتا چند مي خواهي در جنون باشي ؟\r\nلحظه اي بخود آي و راه عقل در پيش\r\nگير.\r\nبهلول گفت: اين روز ها بدنبال عقل رفتن\r\nخيلي جنون می خواهد!\r\n"},{"id":34,"category_id":1,"category_code":"s1","source_id":34,"title":"نردباني دو طرفه","content":"\r\nبهلول را پرسيدند:\r\nحيات آدمي را در مثال به چه ماند؟\r\nبهلول گفت: به نردباني دو طرفه ،كه\r\nاز يك طرف \r\n سن بالا مي رود و از\r\nطرف ديگر \r\n زندگي پايين مي آيد\r\n"},{"id":35,"category_id":1,"category_code":"s1","source_id":35,"title":"مشترك","content":"\r\nبهلول را پرسيدند:\r\nانسانها در روي زمين ، در كدامين \r\nچيز مشتركند ؟ \r\nگفت: در روي زمين ، چنين چيزي نتوان\r\nيافت ،اما در زير زمين \r\n\" خاك سرد و تيره \"\r\nگورستان که مشترک همه ی افراد است!\r\n"},{"id":36,"category_id":1,"category_code":"s1","source_id":36,"title":"عاقبت ثروتمندان و فقيران ","content":"\r\nروزي بهلول در قبرستان بغداد كله هاي \r\nمرده ها را تكان مي داد ، گاهي پر از خاك\r\nمي كرد و سپس خالي مي نمود..\r\nشخصي از او پرسيد:\r\nبهلول ! با اين \" سر هاي مردگان \" چه مي كني؟\r\nگفت: مي خواهم ثروتمندان را از فقيران و \r\nحاكمان را از زير دستان جدا كنم، لكن مي بينم\r\nهمه يكسان هستند.\r\n"},{"id":37,"category_id":1,"category_code":"s1","source_id":37,"title":"عاقلان شهر","content":"بهلول وقتي در بصره بود به او گفتند:\r\nديوانه هاي اين شهر را براي ما بشمار\r\nگفت: ديوانه هاي  شهر آنقدر زيادند كه نمي شود\r\nشمرد ، اگر بخواهيد \r\nعاقلان و خردمندان  را براي شما ميشمارم که اندکند.\r\n"},{"id":38,"category_id":1,"category_code":"s1","source_id":38,"title":"دیوار نوشته های بهلول","content":"روزي بهلول بر هارون وارد شد. در حالي كه\r\nدر ميان عمارت مجلل و نوساز خود مشغول\r\nگردش و تفريح بود . از بهلول خواست كه چند\r\nجمله ناب روي اين بناي جديد بنويسند.\r\nبهلول روي بعضي از ديوارها نوشت.\r\nاي هارون ! تو آب و گل را بلند داشتي و دين را\r\nپايين آوردي و خوار كردي ،گچ را بالا بردي\r\nولي ،\r\nفرمايش پبغمبر را پايين آوردي\r\nاگر مخارج اين ساختمان از مال خودت است ،\r\nخيلي اسراف كرد ه اي و خداوند اسراف كنندگان\r\nرا دوست ندارد و اگر از مال ديگران است ، بر\r\nديگران ظلم روا داشته اي ، خداوند ظالمان را دوست\r\nندارد.\r\n"},{"id":39,"category_id":1,"category_code":"s1","source_id":39,"title":"بهلول در سر سفره ","content":"\r\nروزی بهلول با خلیفه سر یک سفره با همدیگر غذا می خوردند .\r\nناگهان خلیفه در لقمه بهلول موئی دید و گفت : آن مو را ازلقمه خود برگیر.\r\nدر جواب گفت : سر سفره کسی که بدست مهمان نگاه می کند نشستن ندارد و ازمجلس خارج شد . \r\n"},{"id":40,"category_id":1,"category_code":"s1","source_id":40,"title":"بهلول و سرکه ","content":"\r\nمریضی از بهلول برای دفع مرضش سرکه هفت ساله خواست. \r\nبهلول گفت : سرکه هفت ساله دارم ولی به کسی نمی دهم . \r\nمریض پرسید چرا نمی دهی ؟ \r\nبهلول در جواب گفت: اگر می خواستم بدهم هفت سال نمی ماند .\r\n"},{"id":41,"category_id":1,"category_code":"s1","source_id":41,"title":"شوخی با بهلول ","content":"قاضی شهر خواست با بهلول شوخی کند از او پرسید می خواهم مسئله ای از تو بپرسم آیا حاضری جواب بدهی ؟\r\nبهلول گفت : آنچه را می دانم جواب می دهم و هر چه را ندانم از شما خواهم پرسید . \r\nقاضی پرسید : اگر سگی از بامی به بام دیگر جست و بادی از او رها شد آن باد متعلق به کدام یک از صاحبان بامهاست . \r\nبهلول گفت : به هر بامی که نزدیکتر است متعلق به اوست . \r\nقاضی گفت : اگر فاصله هر دو بام برابر باشد چطور ؟\r\nبهلول گفت : نصف باد به صاحب اولی بام و نصف دیگر به دومی تعلق می گیرد .\r\n \r\nقاقی گفت : چنانچه صاحبان خانه غایب باشند تکلیف چیست ؟  \r\nبهلول گفت : در این صورت جزو بیت المال است و به قاضی تعلق می گیرد . \r\n"},{"id":42,"category_id":1,"category_code":"s1","source_id":42,"title":"بهلول و سر تراشی ","content":"روزی بهلول سر شخصی را مشغول به تراشیدن شد.\r\nدر حین کار دستش لرزید و سر آن شخص زخم برداشت . \r\n آن مرد شروع به داد و فریاد کردن که سر مرا بریدی .  \r\nبهلول گفت : خفه شو ! سربریده که حرف نمی زند . \r\n"},{"id":43,"category_id":1,"category_code":"s1","source_id":43,"title":" پرسش خلیفه ازبهلول","content":"\r\nروزي خليفه از بهلول پرسيد: تا به امروز موجودي احمق تر از خود\r\nديده اي؟\r\nبهلول گفت: نه والله، اين نخستين بار است كه ميبينم.\r\n"},{"id":44,"category_id":1,"category_code":"s1","source_id":44,"title":"وجود مبارک خلیفه","content":"روزی خلیفه بهلول را پرسید : زمین را روشنی از چه باشد؟\r\nگفت: از آفتاب \r\nپرسید : شب را سیاهی از چه باشد؟ \r\nگفت : از وجود مبارک خلیفه\r\n"},{"id":45,"category_id":1,"category_code":"s1","source_id":45,"title":"بهلول و ندیم","content":"\r\nیکی از ندیمان خلیفه ٬ بهلول را گفت : اینجا چه نشسته ای؟\r\nبر خیز و نزد خلیفه رو که هر دیوانه را پنج درهم دهد\r\nگفت اگر راست می گویی برو که تو را ده درهم خواهد داد\r\n"},{"id":46,"category_id":1,"category_code":"s1","source_id":46,"title":"دست و پا زدن بهلول","content":"\r\nبهلول را ديدند بر بالاي تپه اي نشسته و دست و پا\r\nهمي زد.\r\nپرسيدند : تو را چه مي شود كه دست و پا همين زني؟\r\nگفت:\r\nنا گهان در  فكر فرو رفته ام ، دست و پا مي زنم\r\nتا از آن بيرون آيم.\r\n"},{"id":47,"category_id":1,"category_code":"s1","source_id":47,"title":"تشييع جنازه قاضي","content":"\r\nقاضي شهر فوت كرد و جمعيت انبوهي به\r\nتشييع آمده بودند . كسي بهلول را گفت: زمان\r\nتشييع جنازه بهتر است آدم در جلوي تابوت قرار\r\nگيرد يا عقب تابوت؟\r\nبهلول گفت: جلو يا عقب تابوت فرقي ندارد ،\r\nبايد سعي كرد:\r\nتوي تابوت قرار نگرفت؟ \r\n"},{"id":48,"category_id":1,"category_code":"s1","source_id":48,"title":"دنيا را چگونه مي بيني؟","content":"\r\nابلهي پرسيد، دنيا را چگونه مي بيني؟ بهلول\r\nگفت:\r\nتو سعادتمند خواهي زيست! \r\nابله در حيرت شد و گفت:\r\nاين چه جوابي است كه به پرسش من مي دهي؟\r\nگفت:\r\nنيكو جوابي است ، زيرا عاقل آنچه را ميداند ،\r\nنمي گويد ، اما آنچه را كه بگويد ، مي داند!!\r\n"},{"id":49,"category_id":1,"category_code":"s1","source_id":49,"title":"بهلول و فاحشه","content":"\r\nزماني دل بهلول از اوضاع زمانه گرفته بود و\r\nدر خرابه اي مشغول ذكر خدا بود. در ضمن\r\nلباسش را براي وصله زدن از تن در آورده بود.\r\nزن بي عفتي چشمش به او افتاد و\r\nبهلول را دعوت به كار بد كرد\r\nبهلول گفت:\r\nوزن دستهاي من چقدر است؟\r\nسپس وزن پاها و وزن تمام اعضا\r\nرا پرسيد!؟\r\nسپس گفت:\r\nكدام عاقل حاضر است بخاطر لذت عضو كوچكي ،\r\nتمامي اعضاي خود را در آتش جهنم بسوزاند.\r\nو از جاي برخاست و نعره اي كشيد و فرار كرد.\r\n"},{"id":50,"category_id":1,"category_code":"s1","source_id":50,"title":"تاثیر دعاي بهلول","content":"آورده اند که اعرابی شترش به مرض جرب مبتلا شده بود . به او توصیه نمودند تا روغن کرچک به اوبمالد . اعرابی شتر را سوار شده تا به شهر رود و روغن بخرد . نزدیک شهر به بهلول گفت:\r\nشترم به مرض جرب مبتلا شده و گفته اند روغن کرچک بمالم خوب می شود ، و لی من عقیده دارم که تاثیر نفس تو بهتر است . استدعا می کنم دعایی بخوانی تا شترم از این مرض نجات پیدا کند . بهلول جواب داد : اگر روغن کرچک بخري و با دعاوي من قاطی کنی ممکن است شتر خوب شود . والادعاي تنها تاثیري نخواهد داشت.\r\n"},{"id":51,"category_id":1,"category_code":"s1","source_id":51,"title":"سوال هارون از بهلول","content":"روزي بهلول بر هارون وارد شد و بر صدر مجلس کنار هارون نشست . هارون از رفتار بهلول رنجیده خاطر گشت و خواست بهلول را در انظار کوچک نماید و سوال نمود آیا بهلول حاضر است جواب معماي مرا بدهد ؟\r\nبهلول گفت : اگر شرط نمایی و مانند دفعات پیش پشت پا نزنی حاضرم . سپس هارون گفت اگر جواب معماي مرا فوري بدهی هزار دینار زر سرخ به تو میدهم و چنانچه در جواب عاجز مانی امر می نمایم تاریش و سبیل تو را بتراشند و بر الاغی سوارت نمایند و در کوچه و بازار بغداد با رسوایی تمام بگردانند. \r\nبهلول گفت که من به زر احتیاجی ندارم ولی با یک شرط حاضرم جواب معماي تو را بدهم  هارون گفت آن شرط چیست ؟\r\nبهلول جواب داد : اگر جواب معماي تو را داد م از تو میخواهم که امر نمایی مگس ها مرا آزار ندهند. \r\nهارون دقیقه اي سر به زیر انداخت و بعد گفت : این امر محال است و مگس ها مطیع من نیستند. \r\nبهلول گفت پس کسی از که در مقابل مگس هاي ناچیز عاجر است چه توقعی می توان داشت . حاضران مجلس بر عقل و جرات بهلول متحیر بودند . هارون هم در مقابل جواب هاي بهلول از رو رفت ولی بهلول فهمید که هارون در صدد تلافی است و براي دل جویی او گفت: \r\nالحال حاضرم بدون شرط جواب معماي تو را بدهم . سپس هارون سوال نمود این چه درختی است (یک سال عمر دارد ) که دوازده شاخه و هرشاخه سی برگ و یک روي آن برگها روشن و روي دیگرتاریک است؟ \r\nبهلول فوري جواب داد این درخت سال و ماه و روز و شب است . به دلیل اینکه هر سال 12 ماه است وهر ماه شامل 30 روز است که نصف آن روز و نصف دیگر شب است . هارون گفت : احسنت صحیح است . حضار زبان به تحسین بهلول گشودند\r\n"},{"id":52,"category_id":1,"category_code":"s1","source_id":52,"title":"قصه مسجد ساختن فضل بن ربیع","content":"آورده اند که فضل بن ربیع در شهر بغداد مسجدي بنا نمود و روزي که سر در مسجد را بنا بود کتیبه کنند ، از فضل سوال نمودند تا دستور دهد عناوین کتیبه را به چه قسم انشاء نمایند . بهلول که در آنجاحاضر بود از فضل پرسید ، مسجد را براي که ساخته اي ؟\r\nفضل جواب داد براي خدا . بهلول گفت اگر براي خدا ساخته اي اسم خود را در کتیبه ذکر نکن!! \r\nفضل عصبانی شده و گفت براي چه اسم خود را در کتبیه ذکر ننمایم ، مردم باید بفهمند بانی این مسجدکیست ؟ بهلول گفت:\r\nپس در کتیبه ذکر کن بانی این مسجد بهلول است . فضل گفت : هرگز چنین کاري نمی کنم \r\nبهلول گفت: اگر این مسجد را براي خود نمایی و شهرت ساخته ، اجر خود را ضایع نمودي . فضل از جواب بهلول عاجز ماند و سکوت اختیار نمود و بعد گفت هرچه بهلول می گوید بنویسید. \r\nآنگاه بهلول امر نمود آیه اي از قرآن کریم را نوشته و بر سردر مسجد نصب نمایند.\r\n"},{"id":53,"category_id":1,"category_code":"s1","source_id":53,"title":"عقل ازدیدگاه بهلول","content":"\r\nروزي هارون الرشید به بهلول گفت : بزرگترین نعمت هاي الهی چیست ؟\r\nبهلول جواب داد بزرگترین نعمت هاي الهی عقل است و خواجه عبدالله انصاري نیز در مناجات خودمیگوید (( خداوندا آنکه را عقل دادي چه ندادي و آنکه را عقل ندادي چه دادی))در خبر است که چون خداوند اراده فرمود که نعمتی را از بنده زایل کند اولین چیزي که از او سلب می نماید عقل اوست و عقل از رزق محسوب شده است . افسوس که حقتعالی این نعمت را از من سلب نموده است. \r\n"},{"id":54,"category_id":1,"category_code":"s1","source_id":54,"title":"پیشنهاد بهلول","content":"روزی بهلول از کوچه ای میگذشت، شخصی بالایش صدا زده گفت: ای بهلول دانا! مبلغی پول دارم، امسال چه بخرم که فایده کنم؟\r\nبهلول :  برو، تمباکو بخر!\r\nمردک تمباکو خرید، وقتیکه زمستان شد، تمباکو قیمت پیدا کرد. به قیمت خوبی به فروش رسید. بقیه هر قدر که ماند، هر چند که از عمر تمباکو میگذشت، چون تمباکوی کهنه قیمت زیاد تری داشت، لهذا به قیمت بسیار خوبتر فروخته میشد وسرانجام فایده بسیاری نصیب اوشد. یک روز باز بهلول از کوچه می گذشت که مردک بالایش صد ا زده و گفت:\r\nای بهلول دیوانه! پارسال کار خوبی به من یاد دادی، بسیار فاید ه کردم، بگو امسال چه خریداری کنم؟\r\nبهلول : برو، پیاز بخر!\r\nمردک که از گفته پارسال بهلول فایده، خوبی برداشته بود، با اعتمادی که به گفته اش داشت هرچه سرمایه داشت و هر چه فایده کرده بود. همه را حریصانه پیاز خرید و به خانه ها گدام کرده منتظر زمستان نشست تا در هنگام قلت پیاز، فایده هنگفتی بر دارد. چون نگاهداری پیاز را نمی دانست، پیاز ها همه نیش کشیده و خراب شد و هر روز صد ها من پیاز گنده را بیرون کرده به خندق میریختند و عاقبت تمام پیاز ها از کار برامده خراب گردید و مردک بیچاره نهایت خساره مند شد.\r\nمردک این مرتبه با قهر و خشونت دنبال بهلول میگشت تا او را یافته و انتقام خود را از وی بگیرد. همینکه به بهلول رسید، گفت: ای بهلول! چرا گفتی که پیاز بخرم و اینقدرها خساره مند شوم؟\r\nبهلول در جوابش گفت: ای برادر! آن وقت که مرا بهلول دانا خطاب کردی، از روی دانایی گفتم«برو، تمباکو بخر» این مرتبه که مرا بهلول دیوانه گفتی، از روی دیوانگی گفتم «برو، پیاز بخر» و این جزای عمل خود تست. مردک خجل شده راه خود را پیش گرفته رفت و خود را ملامت میکرد که براستی، گناه از او بوده...\r\n"},{"id":55,"category_id":1,"category_code":"s1","source_id":55,"title":"چربی دنبه ها","content":"روزی «بهلول» نزد «هارون» می‌رود و درخواست مقداری پیه می‌کند تا با آن « پیه پیاز»، که نوعی غذای ارزان قیمت برای مردم فقیر بوده، فراهم سازد. «هارون» به خدمتکارش می گوید که مقداری شلغم پوست کنده، نزد او بیاورند تا شاهد عکس‌العمل او باشند و بیازمایند که آیا او می‌تواند میان پیه و شلغم پوست‌کنده تمایزی قائل شود.«بهلول» نگاهی به شلغم‌ها می‌اندازد، آن‌ها را به زبانش نزدیک می‌سازد، بو می‌کند و بعد می‌گوید: نمی‌دانم چرا از وقتی که تو حاکم مسلمانان شده‌ای، چربی هم از دنبه رفته‌است!"},{"id":56,"category_id":1,"category_code":"s1","source_id":56,"title":"گلنگ قاضی","content":"روزی بهلول نزد قاضی بغداد نشته بود که قلم قاضی از دستش به زمین افتاد. بهلول به قاضی گفت: جناب قاضی کلنگت افتاد آنرا از زمین بردار. قاضی بمسخره گفت : واقعاً اینکه میگویند بهلول دیوانه است. صحیح است آخر قلم است نه کلنگ\r\nبهلول جواب داد:مردک تودیوانه هستی که هنوز نمیدانی. با احکامیکه به این قلم مینویسی خانه های مردم خراب می کنی، تو بگو قلم است یا کلنگ؟\r\n"},{"id":57,"category_id":1,"category_code":"s1","source_id":57,"title":"روزی خداوند","content":"هارون الرشید به بهلول گفت: می خواهی که وجه معاش تو را متکفل شوم و مایحتاج تو را از خزانه مقرر سازم تا از فکر آن آسوده شوی؟\r\nبهلول گفت: اگر سه عیب در این کار نبود، راضی می شدم؛\r\nاول آنکه تو نمی دانی به چه محتاجم، تا آن را از برای من مهیا سازی\r\nدوم اینکه نمی دانی چه وقت احتیاج دارم تا در آن وقت، وجه را بپردازی\r\nسوم آنکه نمی دانی چقدر احتیاج دارم تا همان مقدار بدهی\r\nولی خداوند تبارک و تعالی که متکفل است این هر سه را می داند آنچه را محتاجم ،وقتی که لازم است و به قدری که احتیاج دارم می رساند\r\nولی با این تفاوت که تو در مقابل پرداخت این وجه، با کوچکترین خطایی ممکن است مرا مورد خشم و غضب خود قرار دهی.\r\n"},{"id":58,"category_id":1,"category_code":"s1","source_id":58,"title":"فیلسوف و بهلول","content":"هارون مجلسی آراسته بود و فیلسوفی از فلاسفهء یونان نیز در آن مجلس حضور داشت. بهلول و دو تن از یارانش وارد شدند. خردمند یونانی سخن می گفت در آن مجلس که ناگاه بهلول در آن میان از او پرسید: کار شما چیست؟ خردمند یونانی می دانست که بهلول دیوانه است و بر آن بود تا دیوانگی او را عیان کند. گفت: من فیلسوفم و کارم این است که اگر عقل از سر کسی بپرد، عقل را به او بازگردانم. بهلول گفت: با این سخنان عقل از سر کسی مپران که بعد مجبور شوی بازش گردانی."},{"id":59,"category_id":1,"category_code":"s1","source_id":59,"title":"عرعر الاغ","content":"می گویند روزی مردی گندم بار الاغ خود کرد و به در خانهء بهلول که رسید، پای الاغ لنگید و الاغ زمین خورد و بار بر زمین ماند. مرد در خانهء بهلول را زد و از او خواست که الاغش را به امانت به او واگذارد تا بار بر زمین نماند. بهلول با خود عهد کرده بود که الاغ خود را به کسی به امانت ندهد. چون پیش تر خیانت دیده بود در امانت، یا بر فرض از الاغش بار زیاد کشیده بودند. گفت: الاغ ندارم و در همان لحظه صدای عر عر الاغش از طویله آمد. مرد گفت: صدای عرعر الاغت را مگر نمی شنوی که چنین دروغ می گویی؟ بهلول گفت: رفیق! ما پنجاه سال است که همدیگر را می شناسیم. تو به حرف من گوش نمی دهی. به صدای عر عر الاغم گوش می دهی احمق!"},{"id":60,"category_id":1,"category_code":"s1","source_id":60,"title":"کوهنوردی","content":"\r\nشخص تنبلي نزد بهلول آمده و پرسيد :\r\nمي خواهم از كوهي بلند بالا روم مي تواني نزديكترين را ه را به من نشان دهي؟\r\nبهلول جواب داد:  نزديكترين و آسانترين راه : نرفتن بالاي كوه است .\r\n"},{"id":61,"category_id":1,"category_code":"s1","source_id":61,"title":"بهلول و الاغ","content":"جمعي در میدان بزرگ ده بر سر ماجرائی حقیر دعوا می کردند و دشنه وخنجر از چپ و راست بر همدیگر حوالت می نمودند.\r\nدر گوشه ی میدان الاغی ایستاده و خاموش در هیاهوی آنان مينگريست.\r\nبهلول به آرامی سر در گوش الاغ برد و گفت:\r\nاینان را ببخشائيد كه نام خود را بر شما نهاده اند.\r\n"},{"id":62,"category_id":1,"category_code":"s1","source_id":62,"title":"شرط ادب","content":"روزی شخصی پیش بهلول بی‌ادبی نمود. بهلول او را ملامت کرد که چرا شرط ادب به جا نیاوردی؟\r\nاو گفت: چه کنم آب و گل مرا چنین سرشته‌اند،\r\nگفت: آب و گل تو را نیکو سرشته‌اند، اما لگد کم خورده است! (تنبیه و تربیت نشده‌ای )\r\n"},{"id":63,"category_id":1,"category_code":"s1","source_id":63,"title":"سوال و جواب قیامت","content":"آورده اند که بهلول بیشتر وقت ها در قبرستان می نشست و روزی که برای عبادت به قبرستان رفته بود وهارون به قصد شکار از آن محل عبور می نمود چون به بهلول رسید گفت : بهلول چه می کنی ؟\r\nبهلول جواب داد : به دیدن اشخاصی آمده ام که نه غیبت مردم را می نمایند و نه از من توقعی دارند و نه من را اذیت و آزار می دهند . هارون گفت: \r\nآیا می توانی از قیامت و صراط و سوال و جواب آن دنیا مرا آگاهی دهی ؟\r\nبهلول جواب داد به خادمین خود بگو تا در همین محل آتش نمایند و \r\nتابه بر آن نهند تا سرخ و خوب داغ شود هارون امر نمود تا آتشی افروختند و تابه بر آن آتش گذاردند تا داغ شد . آنگاه بهلول گفت: \r\nای هارون من با پای برهنه بر این تابه می ایستم و خود را معرفی می نمایم و آنچه خورده ام و هرچه پوشیده ام ذکر می نمایم و سپس تو هم باید پای خو د را مانند من برهنه نمایی و خود را معرفی کنی و\r\nآنچه خورده ای و پوشیده ای ذکر نمایی . هارون قبول نمود. \r\nآنگاه بهلول روی تابه داغ ایستاد و فوری گفت : بهلول و خرقه و نان جو و سرکه و فوری پایین آمد که ابداً پایش نسوخت و چون نوبت به هارون رسید به محض اینکه خواست خود را معرفی نماید نتوانست و\r\nپایش بسوخت و به پایین افتاد .سپس بهلول گفت: \r\nای هارون سوال و جواب قیامت نیز به همین صورت است . آنها که درویش بوده ند و از تجملات دنیایی بهره ندارند آسوده بگذرند و آنها که پایبند تجملات دنیا باشند به مشکلات گرفتار آیند.\r\n"},{"id":64,"category_id":1,"category_code":"s1","source_id":64,"title":"وجه تشابه","content":"فرد ثروتمندی در مجلس میهمانیش قصد مسخره کردن بهلول را داشت و گفت بگو ببینم که چه چیز منو تو شبیه است. \r\nبهلول گفت :جیب من و کله شما که هردو خالیست.و جیب شما کله من  که هردوپر است.\r\n"},{"id":65,"category_id":1,"category_code":"s1","source_id":65,"title":" بهلول و قاری","content":"\r\nبهلول قاری ای را سنگ زد. گفتند: چرا می زنی؟\r\nگفت: زیرا قاری دروغ می گوید.\r\nفتنه‌ای در شهر افتاد. خلیفه بهلول را حاضر کرد.\r\nگفت: من صوتِ او را می‌گویم. قولِ او را نمی گویم.\r\nخلیفه گفت:این چه گونه سخن باشد؟ قول او از صوت او چون جدا باشد؟\r\nبهلول گفت: اگر تو که خلیفه ای فرمانی بنویسی که عاملانِ فلان بقعه چون این فرمان بشنوند باید که حاضر آیند هر چه زودتر، بی هیچ توقّف.\r\nقاصد این فرمان را آنجا برد، خواندند و هر روز می‌خوانند و الّبته نمی‌آیند، در آن خواندن صادق هستند و یا در آن گفتن که سمعاً و طاعتاً؟\r\n"},{"id":66,"category_id":1,"category_code":"s1","source_id":66,"title":"سوال بهلول از مردگان","content":"روزی بهلول ازقبرستان می آمد، از او پرسید ند:\r\nازکجا می آیی ؟ گفت: \r\nازپیش این قافله که دراین سرزمین نزول کرده اند . گفتند: \r\nآیا از آنها سوالا تی هم کرده ای ؟ فرمود: \r\nآری ، از آنها پرسیدم کی از اینجا حرکت و کوچ خواهید نمود ،جواب دادند که: ما انتظار شما را داریم تا هروقت همگی به ما ملحق شدید،حرکت کنیم !\r\n"},{"id":67,"category_id":1,"category_code":"s1","source_id":67,"title":"بهلول و دعای باران","content":"بهلول روزی عده ای از مردم رادید که به بیابان می روند تا از خداوند طلب باران کنند، چونکه چند سالی بودباران نیامده بود\r\nمردم عده ای از اطفال مکتب را همراه خود می بردند.\r\nبهلول پرسید که :اطفال را کجا می برید؟\r\nدرجواب گفتند: چون اطفال گنا هکارنیستند،دعای آنها حتما مستجاب خواهد شد. \r\nبهلول گفت: اگر چنین است،پس نباید هیچ مکتبداری تا کنون زنده باشد.\r\n"},{"id":68,"category_id":1,"category_code":"s1","source_id":68,"title":"بهلول و عبدالله مبارك ","content":"آورده‌اند كه روزی عبدالله مبارك به قصد بهلول به صحرا رفته بهلول را دید كه سراپا برهنه الله‌الله گویان بود. پیش ‌رفته سلام كرد. بهلول جواب سلام بداد . عبدالله مبارك عرض كرد: یا شیخ! استدعا و التماس من آن است كه مرا پندی دهی و نصیحتی كنی كه در دنیا چون باید زیست كرد تا از معصیت دور بود كه من مردی گناهكارم و از عهده نفس سركش برنمی‌آیم. بهلول فرمود یا عبدالله من خود سرگردانم و به خود درمانده‌ام، از من چه توقع داری؟ اگر مرا عقل بودی مردم مرا دیوانه نگفتندی. سخن دیوانگان را چه اثر باشد؟ برو دیگری را طلب كن كه عاقل باشد، و خاموش شد. عبدالله باز الحاح و تضرع كرد كه یا شیخ مرا نومید مكن كه به امیدی آمده‌ام. \r\nچو می‌بینی كه نابینا و چاه‌است\r\nاگر خاموش بنشینی گناه ‌است\r\nبهلول گفت: ای عبدالله تو اول با من چهار شرط بكن كه از سخن دیوانه بیرون نروی . آنگاه تو را پندی گویم كه سبب رستگاری تو باشد و دیگر بر تو گناه ننویسند. عبدالله عرض كرد: آن چهار شرط كدام است؟\r\nبهلول گفت شرط اول آن است كه وقتی گناه كنی و برخلاف امر خدا نمایی روزی او را نخوری. عبدالله گفت: پس رزق كه را خورم؟ بهلول گفت: پس تو مرد عاقلی، روزی او را خوری و خلاف حكم او كنی؟ خود انصاف بده، شرط بندگی چنین باشد؟\r\nعبدالله عرض كرد: حق فرمودی. شرط دوم كدام است؟ بهلول فرمود: شرط دوم این است كه هرگاه خواستی معصیت كنی زنهار كه در ملك او نباشی. عبدالله عرض كرد: این از اولی مشكل‌تر است. همه‌جا ملك خداست پس كجا روم؟ بهلول فرمود: پس قبیح باشد كه رزق او خوری و در ملك او باشی و فرمان او نبری. انصاف بده، شرط بندگی این باشد؟ و حال آن‌كه در كلام خود فرموده است: «ان علینا ایابهم ثم ان علینا حسابهم. \r\nپس عرض كرد: شرط سوم كدام است؟ بهلول فرمود: شرط سوم آن است كه اگر خواهی گناهی و یا خلاف امر او نمایی پنهان شوی كه او تو را نبیند. عبدالله عرض كرد این از همه مشكل‌تر است زیرا كه حق تعالی به همه چیز دانا و در همه جا حاضر و ناظر است و به همه چیز دانا و بیناست. پس صحیح باشد كه روزی او بخوری و در ملك او باشی و در حضور او نافرمانی او كنی با این حال تو دعوی بندگی می‌كنی؟ با آنكه دركتاب خود فرموده «ولا تحسبن الله غافلاً عما بعمل الظالمون» یعنی گمان مبر كه حق تعالی غافل است از عملی كه ظالمان می‌كنند. \r\nعبدالله عرض كرد شرط چهارم كدام است بهلول فرمود: در آن وقت كه ملك‌الموت نزد تو آید به او بگو به من مهلتی بده تا فرزندان و دوستان را وداع كنم و توشه راه آخرت بردارم، آن وقت قبض روح كن. عبدالله عرض كرد این شرط از همه مشكل‌تر است، ملك‌الموت كی در آن وقت مهلت دهد كه نفس برآرم؟ بهلول فرمود: ای مرد عاقل تو می‌دانی كه مرگ را چاره نیست و به هیچ نوع او را از خود دور نتوان كرد و در آن دم ملك‌الموت مهلت ندهد. مبادا در عین معصیت پیك اجل در رسد و یكدم امان‌ات ندهد. چنانچه حق تعالی فرموده «فاذا جاء اجلهم لایستأخزون ساعه و لا یستقدمون» پس ای عبدالله از خواب غفلت بیدار شو و از غرور و مستی هوشیار شو و به كار آخرت دركار شو كه راه دور و دراز در پیش است و از عمر كوتاه توشه دار و كار امروز به فردا مینداز. شاید به فردا نرسی . دم را غنیمت شمار و اهمال در كار آخرت منما! امروز توشه آخرت بردار كه فردا در آنجا ندامت سودی ندهد. پس عبدالله سر برداشت و گفت: یا شیخ نصیحت تو را به جان و دل شنیدم و این چهار شرط را قبول كردم. دیگر بفرما و مزید كن: بهلول فرمود: در خانه اگر كس است یك حرف بس است.\r\n"},{"id":69,"category_id":1,"category_code":"s1","source_id":69,"title":"بازرگان و قاضی ","content":"بازرگانى در شهر بغداد زندگى مى‌کرد و از مال دنیا بسیار داشت. روزى مى‌خواست به سفر حج برود، دار و ندار خود را تبدیل به جواهر کرد و آن‌را در همیانى قرار داد و پیش قاضى برد تا به‌صورت امانت به او بسپرد. قاضى گفت: من امانت کسى را قبول نمى‌کنم، آن‌را بردار و پیش کس دیگرى ببر. بازرگان به درستى قاضى بیشتر مطمئن شد. اصرار کرد که قاضى امانت او را قبول کند. قاضى گفت: من همیان تو را لاک و مهر مى‌کنم، خودت ببر در یکى از قفسه‌هاى دست راست کتابخانه بگذار. بعد از سفر هم بیا و آن‌را بردار. بازرگان قبول کرد. قاضى همیان او را لاک و مهر کرد و بازرگان آن‌را برد و در گوشه‌اى از کتابخانهٔ قاضى گذاشت. بعد به سفر رفت و حج خود را انجام داد و با مقدارى سوغاتى پیش قاضى برگشت. قاضى از گرفتن سوغات امتناع کرد. اما بازرگان اصرار کرد و او پذیرفت. بعد بازرگان سراغ امانتى خود را گرفت. قاضى گفت: کدام امانتی؟ بازرگان نشانى داد. بازرگان گفت: اگر در کتابخانه گذاشته‌اى حتماً همانجا است. \r\n\r\nبازرگان به کتابخانهٔ قاضى رفت و همیان خود را با لاک و مهر دست نخورده، آنجا دید. اما چیزى در همیان نبود. سوراخى در ته کیسه بود. بازرگان بر سر زنان نزد قاضى برگشت و ماجرا را به او گفت. قاضى گفت. خانهٔ من موش‌هاى بزرگى دارد که به جواهر علاقه‌مند هستند! حتماً آنها بره‌اند! \r\n\r\nبازرگان گریان و نالان در کوچه‌ها مى‌رفت که بهلول او را دید و علت گریه‌اش را پرسید. بازرگان قضیه را گفت. بهلول گفت: من کار تو را درست مى‌کنم. از آنجا به نزد برادرش هارو‌ن‌الرشید، که خلیفهٔ بغداد بود، رفت و از او خواست تا حکمى بدهد که او پادشاه موش‌ها است. هارون‌الرشید بسیار خندید و حکم را به‌دست بهلول داد. بهلول پانصد نفر را با بیل و کلنگ اجیر کرد و به خانهٔ قاضى رفت و دستور داد که پى‌هاى خانه را بکنند. نوکران قاضى به او خبر دادند، چه نشسته‌اى که الآن خانه‌ات خراب مى‌شود. قاضى چند نفر را فرستاد تا علت را از بهلول بپرسند. بهلول در جواب گفت: ”مى‌خواهم این خانه را خراب کنم و تمام موش‌هائى را که زیر پى هستند تنبیه کنم و جواهرى را که از حاجى بازرگان برده‌اند، پس بگیرم. فرمان هم از خلیفه گرفته‌ام.“ قاضى آمد و گفت: ”دستم به دامنت. بگو پى‌ها را نکنند، من جواهر بازرگان را صحیح و سالم به تو مى‌دهم تا به صاحبش برسانی. بهلول به کارگران دستور داد دست از کار بکشند. قاضى رفت و جواهر را آورد. \r\n\r\nبهلول با جواهر نزد خلیفه رفت و گفت که بازرگان را بخواهد. بازرگان آمد و بهلول جواهرش را به او پس داد. هارون‌الرشید دستور داد ریش‌هاى قاضى را بتراشند و بر خرى برهنه سوار کنند. چنین کردند. لوحه‌اى هم بر گردنش آویختند که بر روى آن چنین نوشته بودند: ”سزاى خیانت در امانت چنین است.\"\r\n"},{"id":70,"category_id":1,"category_code":"s1","source_id":70,"title":"عمر الاغ","content":"بهلول روزی پای بر جاده ای می گذاشت \r\nکاروان خلیفه ( هارون الرشید ) با جلال و \r\nشکوه آشکار شد .\r\nخلیفه خواست ، با او شوخی کند \r\nگفت : موجب حیرت است که تو را پیاده \r\nمی بینیم ! پس\" الاغت \" کو ؟ \r\nبهلول گفت: همین امروز عمرش را داد به \r\n\" شما \" \r\n"},{"id":71,"category_id":1,"category_code":"s1","source_id":71,"title":"صدای دعا","content":"فردی چند گردو به بهلول داد و گفت : بشکن و بخور و برای من دعا کن ! بهلول گردوها را شکست ولی دعا نکرد ! مرد گفت : گردوها را می خوری نوش جان ! ولی من صدای دعای تو را نشنیدم ! بهلول گفت : مطمئن باش اگر در راه خدا داده ای خدا خودش صدای شکستن گردوها را شنیده است!"},{"id":72,"category_id":1,"category_code":"s1","source_id":72,"title":"چاقوی دسته طلا","content":"بهلول داننده از شاگردان امام جعفر صادق بود ولي چون خلفاي جور امام و شاگردان اورا اذيت مي كردند امام جعفر صادق دستور داده بود تا بهلول خودش را به ديوانگي بزند تااز ستم خلفا مصون بماند. بهلول هم دستور امام را اطاعت كرده بود و با كارهاي كه مي كرد سبب مي شد تا همه فكر كنند بهلول ديوانه شده است وديگر كسي به او كاري نداشته باشد و او در قالب حركات خود هميشه مردم را نصيحت مي كرد وبه آنها ياد مي داد كه  زير بار زور وستم نروند.\r\nبهلول داننده آن شب در خانه اش مهمان داشت ودر حال صحبت با مهمانش بود كه قاصدي از راه رسيد. قاصد پيام قاضي را به او آورده بود. قاضي مي خواست بهلول آن شب شام مهمانش باشد. بهلول به قاصد گفت: از طرف من از قاضي عذر بخواه ، من امشب مهمان دارم ونمي توانم بيايم.\r\nقاصد رفت و چند دقيقه ديگر برگشت وگفت: قاضي مي گويد قدم مهمان بهلول هم روي چشم. بهلول بيايد ومهمانش را هم بياورد.\r\nبهلول با مهمانش به طرف مهماني به راه افتادند او در راه به مهمانش گفت: فقط دقت كن من كجا مي نشينم تو هم آنجا بنشين هرچه مي خورم تو هم بخور تا از تو چيزي نپرسيدند حرفي نزن واگر از تو كاري نخواستند كاري انجام نده.\r\nمهمان در دل به گفته هاي بهلول مي خنديد و مي گفت: نگاه كن يك ديوانه به من نصحيت مي كند.\r\nوقتي به مهماني قاضي رسيدند خانه پراز مهمانان مختلف بود. بهلول كنار در نشست ولي مهمان رفت ودر بالاي خاته نشست. مهمانان كم كم زياد شدند وهر كس مي آمددر كنار بهلول مي نشست و بهلول را به طرف بالاي مجلس مي راند بهلول كم كم به بالاي مجلس رسيد ومهمان به دم در.  \r\nغذا آوردند و مهمانان غذاي خود را خوردند بعد از غذا ميوه آوردند ولي همراه ميوه چاقويي نبود. همه منتظر چاقو بودند تا ميوه هاي خود را پوست بكنند و بخورند. ناگهان چاقوي دسته طلايي ازجيب خود درآورد وگفت: بياييد با اين چاقو ميوه هايتان را پوست بكنيد وبخوريد.\r\nمهمانان به چاقوي طلا خيره شدند. چاقو بسيار زيبا بود ودسته اي از طلا داشت. مهمانان از ديدن چاقوي دسته طلايي در جيب مهمان بهلول كه مرد بسيار فقيري به نظر مي رسيد تعجب كردند. در آن مهماني شش برادر بودند كه وقتي چاقوي دسته طلا راديدند به هم اشاره كردند و براي مهمان بهلول نقشه كشيدند.\r\nبرادر بزرگتر رو به قاضي كه در صدر مجلس نشسته بود و ميزبان بود كرد وگفت: اي قاضي اين چاقو متعلق به پدر ما بود و سالهاي زيادي است كه گم شده است ما اكنون اين چاقو را در جيب اين مرد پيدا كرده ايم ما مي خواهيم داد ما را از اين مرد بستاني و چاقوي ما را به ما برگرداني.\r\nقاضي گفت: آيا براي گفته هايت شاهدي هم داري؟\r\nبرادر بزرگتر گفت: من پنج برادر ديگر در اينجا دارم كه همه شان گفته هاي مرا تصديق خواهند كرد.\r\nپنج برادر ديگر هم گفته هاي برادر بزرگ را تاييد كردند وگفتند چاقو متعلق به پدرآنهاست كه سالها پيش گم شده است.\r\nقاضي وقتي شهادت پنچ برادر را به نفع برادر بزرگ شنيد يقين كرد كه چاقو مال آنهاست و توسط مهمان بهلول به سرقت رفته است. قاضي دستور داد مرد را به زندان ببرند وچاقو را به برادر بزرگ برگردانند.\r\nبهلول كه تا اين موقع ساكت مانده بود گفت: اي قاضي اين مرد امشب مهمان من بود و من او را به اين خانه آوردم اجازه بده امشب اين مرد در خانه من بماند من او را صبح اول وقت تحويل شما مي دهم تا هركاري خواستيد با او بكنيد.\r\nبرادر بزرگ گفت: نه اي قاضي تو راضي نشو كه امشب بهلول اين مرد را به خانه خودش ببرد چون او به اين مرد چيزهاي ياد مي دهد كه حق ما ازبين برود.\r\nقاضي رو به بهلول كرد وگفت: بهلول تو قول مي دهي كه به اين مرد چيزي ياد ندهي تا من او را موقتا آزادكنم ؟\r\nبهلول گفت: اي قاضي من به شما قول ميدهم كه امشب با اين مرد لام تا كام حرف نزنم و اصلا كلمه اي هم به او ياد ندهم.\r\nقاضي گفت: چون اين مرد امشب مهمان بهلول بود برود وشب را با بهلول بماند و فرداصبح بهلول قول مي دهد او را به ما تحويل دهد تا به جرم دزدي به زندانش بيندازيم.\r\nمهمان  برادران به ناچار قبول كردند و بهلول مهمان را برداشت وبه خانه خود برد و در راه اصلا به مهمان حرفي نزد  به محض اينكه به خانه شان رسيدند بهلول زمزمه كنان گفت: بهتر است بروم سري به خر مهمان بزنم حتما گرسنه است واحتياج به غذا دارد.\r\nمهمان كه يادش رفته بود خر خود را در طويله بسته است گفت: نه تو برو استراحت كن من به خر خود سر مي زنم.\r\nبهلول بدون اينكه جواب مهمان را بدهد وارد طويله شد. خر سر در آخور فرو برده بود ودر حال نشخوار علفها بود.\r\nبهلول چوب كلفتي برداشت و به كفل خر كوبيد. خر بيچاره كه علفها را نشخوار مي كرداز شدت در طويله شروع به راه رفتن كرد. بهلول گفت: اي خر خدا مگر من به تو نگفتم وقتي وارد مجلس شدي حرف نزن هر جا كه من نشستم تو هم بنشين اگر از تو چيزي نخواستند دست به جييبت نبر چرا گوش نكردي هم خودت را به دردسر انداختي هم مرا. فردا تو به زندان خواهي رفت آن وقت همه خواهند گفت بهلول مهمان خودش رانتوانست نگه دارد و مهمان به زندان رفت.\r\nبهلول ضربه شديدتري به خر بيچاره زد وگفت: اي خر گوش كن فردا اگر قاضي از تو پرسيد اين چاقو مال توست بگو نه ، من اين چاقو را پيدا كرده ام وخيلي وقت بود كه دنبال صاحبش مي گشتم تا آن را به صاحبش برگردانم ولي متاسفانه صاحبش را پيدا نمي كردم.\r\nاگر اين چاقو مال اين شش برادر است آن را به آنها مي دهم. اگر قاضي از تو پرسيد اينچاقو را از كجا پيدا كرده اي مگر در بيابان چاقو دسته طلا ريخته اند كه تو آن را پيدا كرده اي؟\r\nبگو پدرم سالها پيش كاروان سالار بزرگي بود وهميشه بين شهرها در رفت وآمد بود ومال التجاره زيادي به همراه مي برد و با آنها تجارت مي كرد تا اينكه ما يك شب خبردار شديم كه پدرم را دزدان كشته اند و مال و اموالش را برده اند.\r\nمن بالاي سر پدر بيچاره ام حاضر شدم. پدر بيچاره ام را دزدان كشته بودند وتمام اموالش را برده بودند واين چاقو تا دسته در قلب پدرم فرو رفته بود. من چاقو را برداشتم و پدرم را دفن كردم و از آن موقع دنبال قاتل پدرم مي گردم در هر مهماني اين چاقو رانشان مي دهم ومنتظر مي مانم كه صاحب چاقو پيدا شود ومن قاتل پدرم را پيدا كنم.\r\nاكنون اي قاضي من قاتل پدرم را پيدا كرده ام اين شش برادر پدر مرا كشته اند واموالشرا برده اند. دستور بده تا اينها اموال پدرم را برگردانند و تقاص خون پدرم را پس بدهند.\r\nبهلول كه اين حرفها را در ظاهر به خر مي گفت ولي در واقع مي خواست صاحب خر گفته هاي او را بياموزد. او چوب ديگري به خر زد وگفت: اي خر خدا فهميدي يا تا صبحكتكت بزنم.\r\nصاحب خر گفت: بهلول عزيز نه تنها اين خر بلكه منهم حرفهاي تو را فهميدم و به تو قول مي دهم در هيچ مجلسي بالاتر از جايگاهم ننشينم و اگر از من چيزي نپرسيدند حرف نزنم واگر چيزي ازمن نخواستند دست به جيب نبرم.\r\nبهلول كه مطمئن شده بود مرد حرفهاي او را به خوبي ياد گرفته است رفت و به راحتي خوابيد. فردا صبح بهلول مرد را بيدار كرد و او را منزل قاضي رساند و تحويل داد و خودش برگشت. قاضي رو به مرد كرد وگفت: اي مرد آيا اين چاقو مال توست؟\r\nمرد گفت: نه اي قاضي اين چاقو مال من نيست. من خيلي وقت است كه دنبال صاحب اين چاقو مي گردم تا آن را به صاحبش برگردانم اگر اين چاقو مال اين برادران است من بارغبت اين چاقو را به آنها مي دهم.\r\nقاضي رو به شش برادر كرد وگفت: شما به چاقو نگاه كنيد اگر مال شماست آن رابرداريد.\r\nبرادر بزرگ چاقو را برداشت وبا خوشحالي لبخندي زد وگفت: اي قاضي من مطمئنهستم اين چاقو همان چاقوي گمشده پدر من است.\r\nپنج برادر ديگر چاقو را دست به دست كردند وگفتند بلي اي جناب قاضي اين چاقومطمئنا همان چاقوي گم شده پدر ماست.\r\nقاضي از مرد پرسيد: اي مرد اين چاقو را از كجا پيدا كرده اي؟\r\nمرد گفت: اي قاضي اين چاقو سرگذشت بسيار مفصلي دارد. پدرم سالها پيش كاروان سالار بزرگي بود و هميشه بين شهرها در رفت وآمد بود و مال التجاره زيادي به همراهداشت و شغلش تجارت بود تا اينكه ما يك شب خبردار شديم كه پدرم را دزدان كشته اند و مال واموالش را برده اند من سراسيمه بالاي سر پدر بيچاره ام حاضر شدم. پدربيچاره ام را دزدان   كشته بودند وتمام اموالش را برده بودند و اين چاقوتا دسته در قلبپدر من بود. من چاقو را برداشتم و پدرم را دفن كردم واز آن موقع دنبال قاتل پدرم مي گردم در هر مهماني اين چاقو را نشان مي دهم ومنتظر مي مانم كه صاحب چاقو پيدا شود و من قاتل پدرم را پيدا كنم. اكنون اي قاضي من قاتل پدرم را پيدا كردم. اين ششبرادر پدر مرا كشته اند و اموالش را برده اند. دستور بده تا اينها اموال پدرم را برگردانند وتقاص خون پدرم را بدهند      \r\nشش برادر نگاهي به هم انداختند آنها بدجوري در مخمصه گرفتار شده بودند آنها باادعاي دروغيني كه كرده بودند مجبور بودند اكنون به عنوان قاتل و دزد سالها در زندانبمانند. برادر بزرگ گفت: اي قاضي من زياد هم مطمئن نيستم اين چاقو مال پدر من باشد چون سالهاي زيادي از آن تاريخ گذشته است و احتمالا من اشتباه كرده ام.\r\nبرادران ديگر هم به ناچار گفته هاي او را تاييد كردند وگفتند: كه چاقو فقط شبيه چاقوي ماست ولي چاقويي ما نيست.\r\nقاضي مدت زيادي خنديد و به مرد مهمان گفت: اي مرد چاقويت را بردار و برو پيش بهلول.  من مطمئنم كه اين حرفها را بهلول به تو ياد داده است والا تو هرگز نمي توانستي اين حرفها را بزني.\r\nمرد سجده ی شکر به جای آورد و چاقو را برداشت و خارج شد.\r\n"},{"id":73,"category_id":1,"category_code":"s1","source_id":73,"title":"پس انداز بهلول","content":"آورده اند که بهلول در خرابه اي مسکن داشت و جنب آن خرابه کفش دوزي دکان داشت که پنجره اي\r\nاز کفش دوزي به خرابه بود . بهلول چند درهمی ذخیره نموده بود و آنها را در زیر خاك پنهان کرده و\r\nگه گاه پولها را بیرون آورده و به قدر احتیاج از آنها بر می داشت . از قضا روزي به پول احتیاج داشت\r\nرفت و جاي پولها را زیر و رو نمود ، اثري از پولها ندید . فهمید که پولها را همان کفش دوز که پنجره\r\nدکان او رو به خرابه است برده است . بدون آنکه سرو صدایی کند نزد او رفت و کنار او نشست و بنا\r\nنمود از هر دري سخن گفتن و خوب که سر کفش دوز را گرم کرد آنگاه گفت \r\nرفیق عزیز براي من حسابی بنما٬ کفش دوز گفت بگو تا حساب کنم . بهلول اسم چند خرابه و محل را\r\nبرد و اسم هر محل را که می برد مبلغی هم ذکر می نمود تا آخر و آخرین مرتبه گفت : در این خرابه هم\r\nکه من منزل دارم فلان مبلغ . بعد جمع حسابها را از کفش دوز پرسید که دو هزار دینار می شد . بهلول\r\nتاملی نمود و بعد گفت : رفیق عزیز الحال می خواهم یک مشورت هم از تو بنمایم٬کفش دوز گفت\r\nبکن . بهلول گفت : می خواهم این پولها را که در جاهاي دیگر پنهان نموده ام تمامی را در همین خرابه\r\nکه منزل دارم پنهان نمایم آیا صلاح است یا خیر ؟\r\nکفشدوز گفت : بسیار فکر خوب و عالی است و تمام پولهایی را که در جاهاي دیگر داري در این منزل\r\nپنهان نما . بهلول گفت پس فرمایش تو را قبول می نمایم و می روم تا تمام پولها را بردارم و بیاورم و در\r\nهمین خرابه پنهان نمایم و این را بگفت و فوراً از نزد کفشدوز د ور شد . کفشدوز با خود گفت خوب\r\nاست این مختصر پولی را که از زیر خاك بیرون آورده ام سرجاي خود بگذارم بعد که بهلول تمامی\r\nپولها را آورد به یکبار محل آنها را پیدا نمایم و تمام پولهاي او را بردارم . با این فکر تمام پولهایی را که\r\nاز بهلول ربوده بود سر جایش گذاشت . پس از چند ساعتی که بهلول به آن خرابه آمد و محل پولها را\r\nنگاه کرد دید که کفشدوز پولها را باز آورده و سر جاي خود گذارده است . پولها را برداشت و شکر\r\nخداي را به جاي آورد و آن خرابه را ترك نمود و به محل دیگري رفت ولی کفشدوز هرچه انتظار\r\nبهلول را می کشید اثري از او نمی دید . بعد از چند روز فهمید که بهلول او را فریب داده و به این ترتیب\r\nپولهاي خود را باز گرفته است.\r\n"},{"id":74,"category_id":1,"category_code":"s1","source_id":74,"title":"بهلول و سیاح","content":"آورده اند یکی از سیاحان خارجی وارد شهر بغداد شد و به دربار هارون الرشید بار یافت و چون به\r\nحضور خلیفه رسید سوالاتی چند از وزراء و دانشمندان در حضور خلیفه نمود ولی هیچکدام نتوانستند به\r\nسوالات آن سیاح جواب صحیح دهند. \r\nخلیفه غضبناک شده و به وزراء و علماء دربار گفت اگر جواب این شخص را ندهید ، کلیه اموال شماها\r\nرا به او خواهم داد . حاضرین 24 ساعت مهلت خواستند و خلیفه به آنها فرجه داد و بعد یکی از آنها\r\nگفت فکر می کنم باید به سراغ بهلول برویم و غیر از بهلول دیگري نمی تواند جواب سوالات سیاح را\r\nبه درستی و راستی بدهد . پس به دنبال بهلول رفتند و او را از ماوقع خبردار نمودند و بهلول قبول نمود\r\nکه جواب سوالات سیاح را بدهد . فرداي آن روز که بنا بود در حضور خلیفه جواب سیاح را بدهند ،\r\nبهلول حاضر شد و رو به سیاح نمود و گفت : هر سوالی دارید بنمایید من براي جواب دادن حاضرم\r\nسیاح با عصاي خود دایره اي کشید و بعد رو به بهلول نمود . بهلول بدون معطلی خطی وسط دایره\r\nکشید و آن را به دو قسمت نمود . سیاح باز دایره اي کشید بهلول این دفعه دایره را به چهار قسمت کرد\r\nو با دست یک قسمت را به سیاح نشان داد و گفت : این قسمت خشکی و این سه قسمت آب است. \r\nسیاح دانست که بهلول غرض او را دانسته و به سوالات او درست جواب داده است . پس در حضور\r\nعلماء و حاضرین و خلیفه بهلول را تحسین فراوان نمود و بعد پشت دستش را به زمین گذاشته و انگشتها\r\nرا به طرف آسمان گرفت . بهلول عکس عمل او را نمود . یعنی انگشتها را به زمین گذاشت و پشت\r\nدست را رو به هوا کرد . سیاح بی اندازه او را تحسین نمود و به خلیفه گفت: \r\nاز داشتن چنین عالم دانشمندي باید خیلی به خود بالید . خلیفه پرسید مقصود از این سوال و جواب را\r\nنفهمیدم . سیاح جواب داد من اول دایره کشیدم و مقصودم نشان دادن شکل کره زمین بود٬ بهلول فهمید\r\nو آن را به دو قسمت تقسیم نمود و به من فهماند که به کرویت زمین معتقد است و بلکه رموز را به دو\r\nقسمت نیم کره شمالی و جنوبی تقسیم کرد و مرتبه دوم که دایره کشیدم و آن را به چهار قسمت نمود به\r\nمن فهمانید که زمین چهار قسمت است که یک قسمت آن خشکی و سه قسمت دیگر آب است. \r\nمرتبه سوم که من کف دست را به زمین و انگشتان را به هوا نمودم و غرض من از نباتات و رستنی هاي\r\nزمین و اسرار نمو و رشد آنها بود . بهلول هم با دست خود باران و اشعه آفتاب را نشان داد و فهمانید که\r\nنمو نباتات بوسیله باران و اشعه آفتاب است ، پس به چنین دانشمندي باید بالید . حاضران از حاضر جوابی\r\nبهلول و نجات دادن آنها از غضب هارون شکر خداي را بجا آورده و از بهلول تشکر فراوان نمودند.\r\n"},{"id":75,"category_id":1,"category_code":"s1","source_id":75,"title":"حماقت معاویه و پیروانش","content":"روزی هارون و بهلول در کاخ خلافت نشسته بودند و به ساز و آواز رامشگران و بر بط نوازان گوش میدادند در این هنگام ها رون رو به بهلول کرد و گفت : برادر جان داستانی تاریخی برای ما روایت کن! \r\nبهلول گفت می دانی که وزیر اعظم و مشاور معاویه بود که آ ن دو در زیرکی و باهوشی در میان عرب شهرت داشتند . \r\nعمرو عاص طراح نقشه های عجیب و غریبی بود که دائما علیه خلیفه وقت یعنی حضرت علی(ع) می کشید و با فکر و و اندیشه های شیطانی خود بنیان حکومت معاویه را استوار کرد.\r\nروزی معاویه در کاخ خود نشسته بود و در حضورش عمروعاص ایستاده ناگهان و بدون مقدمه عمروعاص رو به معاویه کرد و گفت : ای پسر ابوسفیان آیا گمان می کنی که خود علی را شکست داده ای و خلیفه مسلمین شده ای ؟ معاویه گفت ای پسر عاص آیا تو اندیشه ای غیر از این داری؟\r\nعمروعاص گفت مسلما اگر مردم احمق و نادان نبودند عناصر معلوم الحالی چون من و تو نمی توانستند برایشان حکومت کنند.\r\nاکنون خریت و جهالت ایشان (هوادارانت)را به تو ثابت می کنم تا بدانی که بر چه مو جوداتی حکومت می کنی.\r\nهنگام ظهر آنها به مسجد رفتند تا خلیفه(معاویه) نماز بگزارد . بعد از نماز عمروعاص رو به مردم کرد و گفت :ای مردم شام می خواهم حدیثی را برایتان نقل کنم که خود صد در صد بر جعلی و ساختگی بودن آن یقین دارم.\r\nمردم کاملا ساکت شدند و گوش به کلام او دادند ! عمرو عاص گفت: حدیث این است که هر کس بتواند زبان خود را از دهانش بیرون آ ورد و آنرا به نوک بینی اش بزند ، بهشت بر او واجب خواهد شد.\r\nدر این هنگام تمام افرادی که در مسجد بودند زبان خود را بیرون آوردند و با سعی و کوشش زیاد آنرا به بینی شان رسانیدند!\r\nعمرو عاص که از نادانی آنها خنده اش گرفته بود سعی می کرد خودش را نگه دارد ، اما با دیدن معاویه که می کوشید زبانش را به بینی اش برساند نتوانست جلوی خود را بگیرد و شروع به خندیدن نمود و برای اینکه اعتبار خود را در بین مردم از دست ندهد از مسجد بیرون رفت. \r\nعصر همان رو ز عمرو عاص معاویه را در کاخ خود ملاقات کرد و به او گفت : بر تو ثابت شد که پیروانت چقدر احمق اند واحمق تر از آنها تو بودی که با وجود اینکه می دانستی این حدیث جعلی است باز سعی می کردی با انجام دادن آن بهشت را بر خود هموار سازی از این رو اطمینان دارم که تو خلیفه احمق ها هستی! \r\nهارون در حالی که از این داستان بهلول خنده اش گرفته بود گفت : راستی ماهم کارهایی انجام میدهیم که بی شباهت به اعمال گذشتگانمان نیست ودر نادانی و حماقت از آنها "},{"id":76,"category_id":1,"category_code":"s1","source_id":76,"title":"بهلول و مستخدم","content":"آورده اند که یکی از مستخدمین خلیفه هارون الرشید ماست خورده و مقداری از آن در ریشش ریخته بود.\r\nبهلول از او سوال نمود چه خورده ای؟ \r\nمستخدم برای تمسخر گفت: کبوتر خورده ام.\r\nبهلول جواب داد: قبل از آنکه بگویی من دانسته بودم و مستخدم پرسید از کجا میدانستی؟\r\nبهلول گفت: فضله ای بر ریشت نمودار است.\r\n"},{"id":77,"category_id":1,"category_code":"s1","source_id":77,"title":"بهلول و صاحب حساب","content":"آورده اند که بهلول به بصره رفت و چون در آن شهر آشنایی نداشت برای مدت کمی اطاقی اجاره نمود ولی آن اطاق\r\nاز بس کهنه ساز و مخروبه بود به محض وزش باد یا بارانی تیرهایش صدا میکرد بهلول پیش صاحب خانه رفته و\r\nگفت اطاقی که به من داده اید بی اندازه خطرناک است زیرا به محض وزش مختصر بادی صدا از سقف دیوارش شنیده\r\nمیشود.\r\nصاحب خانه که مرد شوخی بود در جواب بهلول گفت عیبی ندارد البته می دانید که تمام موجودات به موقع حمد و تسبیح\r\nخدای را می گویند و این صدای تسبیح و حمد اطاق است. \r\nبهلول گفت: \r\nصحیح است ولی چون تسبیح و تحلیل موجودات به سجده منجر میشود من از ترس سجده اطاق خواستم زودتر فکری\r\nبنمایم.\r\n"},{"id":78,"category_id":1,"category_code":"s1","source_id":78,"title":"بهلول و عابر ","content":"روزی بهلول در کنار چشمه ای نشسته بود . مردی که از آنجا می گذشت از بهلول پرسید:  چند ساعت دیگر به ده بعدی خواهم رسید ؟\r\nبهلول گفت : راه برو . آن مرد پنداشت که بهلول نشنیده است\r\nدوباره سوال کرد : مگر نشنیدی ؟ پرسیدم چند ساعت دیگر به ده بعدی خواهم رسید ؟\r\nبهلول گفت : راه برو . آن مرد پنداشت که بهلول دیوانه است و رفتن را پیشه کرد. \r\nزمانی که چند قدمی راه رفته بود ،بهلول به بانگ بلند گفت : ای مرد ، یک ساعت دیگر بدان ده خواهی رسید \r\nمرد گفت : چرا اول نگفتی ؟\r\nبهلول گفت : چون راه رفتن تو را ندیده بودم ، نمی دانستم تند می روی یا کند. \r\nحال که دیدم دانستم که تو یک ساعت دیگر به ده خواهی رسید.\r\n"},{"id":79,"category_id":1,"category_code":"s1","source_id":79,"title":"گفتگوی بهلول با مرد عرب","content":"\r\nبهلول روزی با عربی همراه شد \r\nاز عرب پرسید :اسم شما چیست ؟\r\nعرب در جواب گفت :مطر .یعنی (باران)  \r\nبهلول گفت : کنیه تو چیست ؟\r\nعرب گفت :ابوالغیث . یعنی ( پدر باران)\r\nبهلول پرسید : پدرت نامش چیست ؟ \r\nعرب گفت : فرات .بهلول پرسید : کنیه پدرت چیست ؟\r\nعرب گفت : ابوالفیض . یعنی (پدر آب باران) \r\nبهلول پرسید :نام مادرت چیست ؟\r\nعرب جواب داد : سحاب . یعنی (ابر)\r\nبهلول پرسید : کنیه او چیست ؟\r\nعرب گفت : ام اابحر. یعنی ( مادر دریا )\r\nبهلول گفت : تو رو به خدا صبر کن تا کشتی پیدا کنم و سوار شوم ، وگر نه می ترسم در همراهی تو غرق شوم.\r\n"},{"id":80,"category_id":1,"category_code":"s1","source_id":80,"title":"نزاع دو همسایه","content":"دو همسایه باهم نزاع کرده نزد داروغه آمدند .\r\nداروغه سبب نزاع را ازآندو سوال کرد وهر کدام ازآنها ادعا می کرد که :\r\nلا شه سگ مرده ای که در کو چه افتاده ، به خانه طرف نزدیک تراست وباید\r\n آن را از کوچه بردارد .\r\nاتفا قا بهلول هم درآن محضربود.\r\nداروغه ازبهلول سوال کرد :\r\nدراین باب عقیده شما چیست؟  بهلول گفت :\r\nکوچه مال عموم است وبه هیچکدام ازاین دو نفر مربوط نیست واین کار بعهده داروغه شهراست که باید دستور دهد تا لا شه سگ رااز میان کوچه فوری بردارند .\r\n"}];
